window.TADABBUR_NAML = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة النمل (٢٧)، سورةٌ مكّيّةٌ تُفتتَح بـ«طس»، محورُها بشارةُ المؤمنين وقصصُ الأنبياء (موسى، داود وسليمان مع الهدهد وملكةِ سبأ والنمل، صالح، لوط) وبراهينُ التوحيدِ والبعث؛ فيها آيةُ «أمن يجيب المضطر». بُدئت بذكرِ القرآنِ هدًى وبشرى. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، ونصُّ الآيةِ لا يُكتَب هاهنا بأيدينا، بل يُنقَل عند القراءةِ من مصحفٍ محقَّقٍ مضبوط، صيانةً له من الخطأ."},"n":27,"name":"النمل","total_ayahs":93,"audio":[3,19,30,40,44,59,62,80,88,93],"passages":[{"title":"القرآنُ هدًى وبشرى، وحالُ المكذّبين","range":[1,6],"theme":"القرآنُ هدًى وبشرى للمؤمنين المقيمين الصلاةَ الموقنين بالآخرة، وسوءُ العاقبةِ لمنكري البعث، والقرآنُ من لدنِ الحكيمِ العليم","verses":[{"n":1,"reflection":{"text":"«طس تلك آيات القرآن وكتاب مبين» — طس حروفٌ مقطّعةٌ للتنبيهِ على إعجازِ القرآن، هذه آياتُ القرآنِ والكتابِ المبينِ الموضِّحِ للحقّ؛ ففي هذا تعظيمُ شأنِ القرآنِ ووضوحِ بيانه؛ فعظّم القرآنَ واتّبع بيانه، فهو كتابٌ مبينٌ لا لبسَ في هداه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المبينِ واتّباعُ بيانه."},"action":{"text":"عظّم القرآنَ في قلبك، واتّبع بيانه المبين، وسلّم لله في الحروفِ المقطّعةِ فيما استأثر بعلمه؛ فالقرآنُ كتابٌ موضِّحٌ للحقّ، فاجعله إمامك في كلِّ أمرك، متدبّرًا لآياته، عاملًا بمحكمه."}},{"n":2,"reflection":{"text":"«هدى وبشرى للمؤمنين» — هو هدايةٌ إلى الحقِّ وبشارةٌ بالثوابِ للمؤمنين؛ ففي هذا أنّ القرآنَ هدًى وبشرى لمن آمن؛ فاطلب هدايتك وبشراك في القرآن، فمن آمن به وعمل به ناله هداه وبشراه، ومن أعرض حُرِم النورَ والبشرى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدى والبشرى في القرآن."},"action":{"text":"اطلب هدايتك وبشراك في القرآن، فهو هدًى للقلوبِ وبشرى للمؤمنين بحسنِ العاقبة؛ فأقبل عليه تلاوةً وتدبّرًا وعملًا لتكون من أهلِ هداه وبشراه؛ فالنورُ والبشرى موقوفان على الإيمانِ به واتّباعه."}},{"n":3,"reflection":{"text":"«الذين يقيمون الصلاة ويؤتون الزكاة وهم بالآخرة هم يوقنون» — المؤمنون هم الذين يقيمون الصلاةَ ويؤتون الزكاةَ ويوقنون بالآخرة؛ ففي هذا بيانُ علاماتِ الإيمانِ الصادق؛ فأقم صلاتك وآتِ زكاتك وأيقن بالآخرة، فهذه ثمراتُ الإيمانِ التي تُصدّق دعواه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ علاماتِ الإيمانِ الصادق."},"action":{"text":"أقم صلاتك بحدودها، وآتِ زكاةَ مالك طيّبةً بها نفسك، وأيقن بالآخرةِ يقينًا يحملك على العمل؛ فهذه علاماتُ المؤمنين الصادقين؛ فحقّقها في نفسك لتنال هدى القرآنِ وبشراه، فالإيمانُ قولٌ وعملٌ ويقين."}},{"n":4,"reflection":{"text":"«إن الذين لا يؤمنون بالآخرة زينا لهم أعمالهم فهم يعمهون» — إنّ الذين لا يؤمنون بالآخرةِ زيّنّا لهم أعمالهم السيّئةَ عقوبةً فهم يتحيّرون؛ ففي هذا أنّ إنكارَ البعثِ يورث الحيرةَ والعمى؛ فآمن بالآخرةِ لينضبط عملك، فمن أنكرها زُيِّن له باطلُه فتاه، والإيمانُ بها ميزانٌ يقوّم العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالآخرةِ ميزانٌ يقوّم العمل."},"action":{"text":"رسّخ إيمانك باليومِ الآخر، فهو الميزانُ الذي يقوّم عملك ويعصمك من الحيرة؛ فمن أنكر البعثَ زُيِّن له سوءُ عمله فتاه في ضلاله؛ فاستحضر لقاءَ الله عند كلِّ عملٍ يقوّم مسارك، ويحفظك من زَيْنِ الباطل."}},{"n":5,"reflection":{"text":"«أولئك الذين لهم سوء العذاب وهم في الآخرة هم الأخسرون» — أولئك المنكرون لهم أسوأُ العذابِ في الدنيا، وهم في الآخرةِ أشدُّ الناسِ خسرانًا؛ ففي هذا عاقبةُ الإعراضِ عن الآخرة؛ فاحذر خسرانَ الآخرةِ الذي لا جبرَ له، فاعمل لها قبل فواتِ الأوان، فخسارةُ الآخرةِ هي الخسارةُ الكبرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من خسرانِ الآخرةِ الأكبر."},"action":{"text":"احذر أن تكون من الأخسرين في الآخرة بإعراضك عن الاستعدادِ لها؛ فخسارتها لا تُجبَر ولا تُستدرَك؛ فقدّم لآخرتك عملًا صالحًا قبل أن تُفاجأ بسوءِ العذاب؛ فاجعل همّك النجاةَ يومَ يخسر المبطلون، فالرابحُ من ربح آخرته."}},{"n":6,"reflection":{"text":"«وإنك لتلقى القرآن من لدن حكيم عليم» — وإنك يا محمدُ لتتلقّى القرآنَ من عند اللهِ الحكيمِ في تدبيره، العليمِ بخلقه؛ ففي هذا تقريرُ مصدرِ القرآنِ الإلهيّ؛ فتلقَّ القرآنَ بيقينٍ أنه من لدنِ الحكيمِ العليم، فما فيه من حكمٍ فعن حكمةٍ وعلم، فسلّم له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الحكيم","العليم"],"heart_state":{"text":"تلقّي القرآنِ بيقينٍ أنه من الحكيمِ العليم."},"action":{"text":"تلقَّ القرآنَ موقنًا أنه تنزيلٌ من الحكيمِ العليمِ الذي أحكم شرعه بعلمه؛ فسلّم لأحكامه، واعلم أنّ كلَّ ما فيه صادرٌ عن حكمةٍ بالغةٍ وعلمٍ محيط؛ فلا تعترض على حكمٍ، وأيقن أنّ فيه خيرك، فمصدرُه يوجب التسليم."}}]},{"title":"موسى والنداءُ في الوادِ المقدّسِ والآيات","range":[7,14],"theme":"نداءُ موسى وتأمينُه وآيتا العصا واليد في تسعِ آيات، وجحودُ فرعونَ وقومِه الحقَّ ظلمًا وعلوًّا","verses":[{"n":7,"reflection":{"text":"«إذ قال موسى لأهله إني آنست نارا سآتيكم منها بخبر أو آتيكم بشهاب قبس لعلكم تصطلون» — حين قال موسى لأهله: إني أبصرتُ نارًا سآتيكم منها بخبرِ الطريقِ أو بقبسٍ تستدفئون به؛ ففي هذا بدءُ قصةِ موسى، وحرصُه على نفعِ أهله؛ فكن ساعيًا في نفعِ أهلك، فما ساق الله موسى إلا لخيرٍ عظيم، ولعلّ في مشقّتك بابَ فضلٍ لا تدريه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ في نفعِ الأهلِ والثقةُ بتدبيرِ الله."},"action":{"text":"اسعَ في نفعِ أهلك وقضاءِ حوائجهم كحرصِ موسى، وثِق بأنّ ما يسوقه الله إليك قد يكون بابَ خيرٍ عظيمٍ لا تدريه؛ فربّ مشقّةٍ خبّأ الله خلفها فضلًا، فامضِ في الخيرِ محتسبًا، مسلّمًا أمرك لتدبيرِ ربّك."}},{"n":8,"reflection":{"text":"«فلما جاءها نودي أن بورك من في النار ومن حولها وسبحان الله رب العالمين» — فلما جاء النارَ نُودِي أن بُورِك من في النارِ ومن حولها، وتنزيهًا لله ربِّ العالمين؛ ففي هذا شرفُ الموضعِ بتجلّي الله، وتنزيهُه سبحانه؛ فنزّه الله عن كلِّ نقص، واعلم أنّ البركةَ من عند الله يضعها حيث شاء، فاطلبها منه وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله وطلبُ البركةِ منه وحده."},"action":{"text":"نزّه الله ربَّ العالمين عن كلِّ نقصٍ عند كلِّ آيةٍ من آياته، واطلب البركةَ منه وحده فهو مصدرها؛ فبارك موسى في ذلك الموطنِ المبارَك؛ فاجعل لسانك رطبًا بتسبيحِ الله وتنزيهه، مستحضرًا عظمته، طالبًا بركته في عملك وعمرك."}},{"n":9,"reflection":{"text":"«يا موسى إنه أنا الله العزيز الحكيم» — يا موسى إنه أنا الله العزيزُ الغالبُ، الحكيمُ في صنعه؛ ففي هذا تعريفُ الله نفسَه لموسى بالعزّةِ والحكمة؛ فاعرف ربّك بأنه العزيزُ الحكيم، فاطمئنَّ لعزّتِه أن تنصرك، ولحكمته أن تدبّر أمرك خيرَ تدبير.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"معرفةُ الله بالعزّةِ والحكمةِ والطمأنينةُ إليه."},"action":{"text":"اعرف ربّك بأنه العزيزُ الذي لا يُغلَب، الحكيمُ الذي لا يعبث؛ فاطمئنَّ إلى عزّتِه أن تنصرك وتكفيك، وإلى حكمته أن تدبّر أمرك أحسنَ تدبير؛ فمن عرف ربّه بهذين الاسمين وثق بنصرِه وحكمته، فسكن قلبه، وصلح عمله."}},{"n":10,"reflection":{"text":"«وألق عصاك فلما رآها تهتز كأنها جان ولى مدبرا ولم يعقب يا موسى لا تخف إني لا يخاف لدي المرسلون» — وألقِ عصاك، فلما رآها تتحرّك كأنها حيّةٌ ولّى هاربًا، فقيل: يا موسى لا تخف، إني لا يخاف عندي المرسلون؛ ففي هذا تأمينُ الله لرسله؛ فاطمئنَّ في حضرةِ الله، فمن كان مع الله فلا خوفَ عليه، والأمنُ الحقُّ في قربه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأمنُ في حضرةِ الله وعدمُ الخوفِ مع قربه."},"action":{"text":"اطمئنَّ إذا كنت في طاعةِ الله وقربه، فإنّ الله يؤمّن أولياءه «لا يخاف لدي المرسلون»؛ فلا تدع الخوفَ من المخلوقين يزلزلك ما دمت في جانبِ الله؛ فاجعل الله ملجأك، فمن كان معه فهو في أمنٍ وحرزٍ من كلِّ ما يخاف."}},{"n":11,"reflection":{"text":"«إلا من ظلم ثم بدل حسنا بعد سوء فإني غفور رحيم» — لكن من ظلم نفسه ثم تاب فبدّل حُسنًا بعد سوءٍ فإني غفورٌ رحيم؛ ففي هذا سعةُ مغفرةِ الله لمن تاب؛ فمهما أذنبت فبابُ التوبةِ مفتوح، فبدّل السوءَ بالحسنى، فالله غفورٌ رحيمٌ يقبل التائبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الرجاءُ في مغفرةِ الله وتبديلُ السوءِ بالحسنى."},"action":{"text":"لا تيأس من رحمةِ الله مهما أذنبت، فبابُ التوبةِ مفتوحٌ لمن ظلم نفسه ثم بدّل الحسنى بعد السوء؛ فبادر بالتوبةِ والعملِ الصالحِ يمحُ الله سيّئاتك؛ فهو الغفورُ الرحيمُ الذي يقبل التوبةَ ويبدّل السيّئاتِ حسنات، فأقبل عليه نادمًا مستغفرًا."}},{"n":12,"reflection":{"text":"«وأدخل يدك في جيبك تخرج بيضاء من غير سوء في تسع آيات إلى فرعون وقومه إنهم كانوا قوما فاسقين» — وأدخل يدك في جيبك تخرج بيضاءَ من غيرِ برصٍ، في جملةِ تسعِ آياتٍ إلى فرعونَ وقومه، إنهم كانوا قومًا خارجين عن الطاعة؛ ففي هذا تأييدُ الله لموسى بالآيات؛ فاعلم أنّ الله يؤيّد أولياءه بما يشاء، وأنّ الفسقَ سببُ استحقاقِ العذاب، فالزم الطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بتأييدِ الله لأوليائه، والحذرُ من الفسق."},"action":{"text":"أيقن بأنّ الله يؤيّد أولياءه بالآياتِ والبراهينِ كما أيّد موسى بالتسع؛ واحذر الفسقَ والخروجَ عن طاعةِ الله فهو سببُ استحقاقِ العذابِ كما استحقّه فرعونُ وقومه؛ فالزم الطاعةَ والاستقامة، وثِق بأنّ الله ناصرٌ للحقِّ وأهله."}},{"n":13,"reflection":{"text":"«فلما جاءتهم آياتنا مبصرة قالوا هذا سحر مبين» — فلما جاءتهم آياتُنا واضحةً بيّنةً قالوا: هذا سحرٌ ظاهر؛ ففي هذا عنادُ المكذّبين وردُّهم الحقَّ الواضحَ بالباطل؛ فلا يغرّنك ردُّ المعاندين للحقّ بالتهم، فتلك عادةُ المكابرين مع الآياتِ البيّنة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ رغمَ ردِّ المعاندين الحقَّ بالتهم."},"action":{"text":"لا يزلزلك أن يردَّ المعاندون الحقَّ الواضحَ بتهمة السحرِ أو غيرها، فتلك عادةُ المكابرين مع البيّنات؛ فامضِ في الحقِّ واثقًا بوضوحه؛ فالآيةُ المبصرةُ لا يردّها إلا مكابرٌ معاند، والعبرةُ بقبولِ المنصفين لا بجحودِ الجاحدين."}},{"n":14,"reflection":{"text":"«وجحدوا بها واستيقنتها أنفسهم ظلما وعلوا فانظر كيف كان عاقبة المفسدين» — وجحدوا بالآياتِ وقلوبُهم موقنةٌ بها ظلمًا وتكبّرًا، فانظر كيف كانت عاقبةُ المفسدين؛ ففي هذا أنّ الجحودَ قد يكون مع العلم، وأنّ عاقبةَ الإفسادِ الهلاك؛ فاحذر جحودَ الحقِّ بعد معرفته، فتلك جريمةُ الظلمِ والكبر، وعاقبتُها سوءُ المصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من جحودِ الحقِّ بعد العلمِ به."},"action":{"text":"احذر أشدَّ الحذرِ أن تجحد حقًّا استيقنه قلبك، فذلك ظلمٌ وكبرٌ كان جحودَ فرعونَ وقومه؛ فمن عرف الحقَّ لزمه اتّباعه لا مكابرته؛ فاعتبر بعاقبةِ المفسدين الجاحدين، والزم الإذعانَ للحقِّ متى تبيّن، فالعنادُ بابُ الهلاك."}}]},{"title":"داودُ وسليمانُ: العلمُ والنعمةُ ومنطقُ الطيرِ ووادي النمل","range":[15,19],"theme":"شكرُ داودَ وسليمانَ على العلم، وتحدّثُ سليمانَ بالنعمة، وحكمةُ النملة، ودعاءُ سليمانَ بالشكرِ والعملِ الصالح","verses":[{"n":15,"reflection":{"text":"«ولقد آتينا داود وسليمان علما وقالا الحمد لله الذي فضلنا على كثير من عباده المؤمنين» — ولقد آتينا داودَ وسليمانَ علمًا فقالا: الحمدُ لله الذي فضّلنا على كثيرٍ من عباده المؤمنين؛ ففي هذا شرفُ العلمِ وشكرُ نعمتِه؛ فاشكر الله على ما آتاك من علم، فالعلمُ نعمةٌ تستوجب الحمدَ والتواضع، لا الكبرَ والاستطالة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ العلمِ والتواضعُ بها."},"action":{"text":"احمد الله على ما آتاك من علمٍ نافع، واعلم أنه فضلٌ منه يستوجب الشكرَ والتواضعَ لا الكبر؛ فاقتدِ بداودَ وسليمانَ إذ حمدا الله على العلم؛ فوظّف علمك في طاعةِ الله ونفعِ الخلق، ولا تستطل به على أحد، فالعلمُ أمانةٌ ومسؤولية."}},{"n":16,"reflection":{"text":"«وورث سليمان داود وقال يا أيها الناس علمنا منطق الطير وأوتينا من كل شيء إن هذا لهو الفضل المبين» — وورث سليمانُ داودَ النبوّةَ والملك، وقال: يا أيها الناسُ عُلِّمنا فهمَ لغةِ الطير، وأُوتينا من كلِّ شيءٍ، إنّ هذا لهو الفضلُ الظاهر؛ ففي هذا إظهارُ نعمةِ الله والتحدّثُ بها شكرًا؛ فتحدّث بنعمةِ ربّك اعترافًا بفضله لا فخرًا، ونسبةً للفضلِ إلى معطيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التحدّثُ بنعمةِ الله شكرًا لا فخرًا."},"action":{"text":"تحدّث بنعمةِ الله عليك اعترافًا بفضله وشكرًا له لا فخرًا على الخلق، كما تحدّث سليمانُ بما أوتي؛ فانسب كلَّ فضلٍ إلى معطيه سبحانه؛ فإظهارُ النعمةِ على وجهِ الشكرِ عبادة، وكتمانُها كفرانٌ، وادّعاؤها لغيرِ الله جحود، فاجعلها شكرًا خالصًا."}},{"n":17,"reflection":{"text":"«وحشر لسليمان جنوده من الجن والإنس والطير فهم يوزعون» — وجُمِع لسليمانَ جنودُه من الجنِّ والإنسِ والطيرِ فهم يُساقون منظّمين؛ ففي هذا عظمُ ملكِ سليمانَ وحسنُ نظامِه؛ فاعلم أنّ ما أوتي سليمانُ فضلٌ من الله، وأنّ حسنَ النظامِ من تمامِ النعمة، فرتّب أمرك واشكر واهبَ الملك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بأنّ الملكَ فضلُ الله، وحسنُ تدبيرِ الأمر."},"action":{"text":"أيقن بأنّ كلَّ ملكٍ وقوّةٍ فضلٌ من الله يؤتيه من يشاء، ورتّب أمورك بحسنِ نظامٍ وتدبيرٍ كما نُظِّمت جنودُ سليمان؛ فالإتقانُ والتنظيمُ من شكرِ النعمة؛ فاحمد الله على ما آتاك من قدرة، واستعملها في طاعته، مدبّرًا أمرك بإحسان."}},{"n":18,"reflection":{"text":"«حتى إذا أتوا على واد النمل قالت نملة يا أيها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون» — حتى إذا بلغوا وادي النملِ قالت نملةٌ: يا أيها النملُ ادخلوا مساكنكم لئلا يحطمكم سليمانُ وجنودُه وهم لا يشعرون؛ ففي هذا حكمةُ النملةِ في تحذيرِ قومها، وعذرُها لسليمانَ بعدمِ الشعور؛ فاحذر على من تحت يدك، واحمل الناسَ على أحسنِ المحامل، فالنملةُ عذرت ولم تتّهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"النصحُ لمن تحت يدك، وحملُ الناسِ على أحسنِ المحامل."},"action":{"text":"انصح لمن تحت رعايتك وحذّرهم ما يضرّهم كما فعلت النملةُ بقومها؛ واحمل أفعالَ الناسِ على أحسنِ المحامل، فالنملةُ التمست العذرَ لسليمانَ «وهم لا يشعرون» ولم تتّهم؛ فكن ناصحًا لمن تحتك، حسنَ الظنِّ بإخوانك، ملتمسًا لهم المعاذير."}},{"n":19,"reflection":{"text":"«فتبسم ضاحكا من قولها وقال رب أوزعني أن أشكر نعمتك التي أنعمت علي وعلى والدي وأن أعمل صالحا ترضاه وأدخلني برحمتك في عبادك الصالحين» — فتبسّم سليمانُ ضاحكًا من قولِ النملةِ وقال: ربِّ ألهمني شكرَ نعمتك عليّ وعلى والديّ، ووفّقني لعملٍ صالحٍ ترضاه، وأدخلني برحمتك في عبادك الصالحين؛ ففي هذا أدبُ سليمانَ في مقابلةِ النعمةِ بالشكرِ والدعاء؛ فقابل نعمَ الله بالشكرِ والدعاءِ بالتوفيقِ للعملِ الصالح، واطلب الرحمةَ لا الاتّكالَ على العمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمةِ وطلبُ التوفيقِ للعملِ الصالحِ والرحمة."},"action":{"text":"إذا رأيت نعمةً من الله فقابلها بالشكرِ والدعاءِ كدعاءِ سليمان «رب أوزعني أن أشكر»، واسأل الله التوفيقَ لعملٍ صالحٍ يرضاه، واطلب دخولَ الجنّةِ برحمتِه لا بعملك؛ فاجعل هذا الدعاءَ وِردًا لك؛ فالشكرُ يحفظ النعمة، وطلبُ الرحمةِ يعصم من العُجب."}}]},{"title":"الهدهدُ ونبأُ سبأ ودعوةُ التوحيد","range":[20,26],"theme":"تفقّدُ سليمانَ الطير، وخبرُ الهدهدِ عن ملكةِ سبأ وسجودِهم للشمس، ودعوتُهم إلى السجودِ لله عالمِ الغيبِ ربِّ العرشِ العظيم","verses":[{"n":20,"reflection":{"text":"«وتفقد الطير فقال ما لي لا أرى الهدهد أم كان من الغائبين» — وتفقّد سليمانُ الطيرَ فقال: ما لي لا أرى الهدهدَ أم كان من الغائبين؟ ففي هذا حسنُ تفقّدِ الراعي لرعيّته، وتعهّدُه لجندِه؛ فتفقّد من تحت يدك ولا تغفل عنهم، فالراعي المسؤولُ يعرف أحوالَ رعيّته ويسأل عن غائبهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفقّدُ الراعي لرعيّته وتعهّدُ أحوالهم."},"action":{"text":"تفقّد من تحت رعايتك من أهلٍ أو عملٍ أو من تسوسهم، ولا تغفل عن أحوالهم كما تفقّد سليمانُ طيرَه حتى الهدهد؛ فالراعي مسؤولٌ عن رعيّته يعرف حاضرهم ويسأل عن غائبهم؛ فكن متعهّدًا لمن ولّاك الله أمرهم، عادلًا في تفقّدهم."}},{"n":21,"reflection":{"text":"«لأعذبنه عذابا شديدا أو لأذبحنه أو ليأتيني بسلطان مبين» — لأعذّبنّ الهدهدَ عذابًا شديدًا أو لأذبحنّه أو ليأتينّي بحجّةٍ بيّنةٍ على غيبته؛ ففي هذا حزمُ سليمانَ مع العدلِ في طلبِ العذر؛ فكن حازمًا في تأديبِ المقصّر، لكن أعطِه فرصةَ إبداءِ عذره، فالحزمُ يقارنه العدلُ لا التسرّع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحزمُ في التأديبِ مع العدلِ في قبولِ العذر."},"action":{"text":"كن حازمًا في تأديبِ المقصّرِ ممّن تحت يدك، لكن اقرن حزمك بالعدلِ فأعطه فرصةَ بيانِ عذره كما استثنى سليمانُ «أو ليأتيني بسلطان مبين»؛ فلا تعاقب قبل سماعِ الحجّة؛ فالجمعُ بين الحزمِ والإنصافِ من العدل، والتسرّعُ في العقوبةِ ظلم."}},{"n":22,"reflection":{"text":"«فمكث غير بعيد فقال أحطت بما لم تحط به وجئتك من سبإ بنبإ يقين» — فمكث الهدهدُ زمنًا يسيرًا ثم قال: علمتُ ما لم تعلمه، وجئتك من سبإٍ بخبرٍ يقين؛ ففي هذا أنّ العلمَ قد يكون عند الصغيرِ ما ليس عند الكبير، وأنّ العبرةَ بصدقِ الخبر؛ فلا تحتقر من دونك، فقد يكون عنده علمٌ تجهله، وتواضع لقبولِ الحقِّ ممّن جاء به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لقبولِ الحقِّ ولو من الأدنى منزلةً."},"action":{"text":"لا تحتقر من هو دونك منزلةً، فقد يعلم ما تجهله كما علم الهدهدُ ما لم يعلمه سليمانُ النبيُّ الملك؛ فتواضع لقبولِ الحقِّ والعلمِ ممّن جاء به كائنًا من كان؛ فالحكمةُ ضالّةُ المؤمنِ أنّى وجدها أخذها؛ فلا يمنعك كِبرٌ أو منصبٌ من الاستفادةِ ممّن دونك."}},{"n":23,"reflection":{"text":"«إني وجدت امرأة تملكهم وأوتيت من كل شيء ولها عرش عظيم» — إني وجدتُ امرأةً تملك أهلَ سبأٍ وأُوتيت من كلِّ أسبابِ الملك، ولها عرشٌ عظيم؛ ففي هذا وصفُ ما رآه الهدهدُ بدقّةٍ وأمانة؛ فكن دقيقًا أمينًا في نقلِ الخبر، فالتثبّتُ في النقلِ وأمانةُ الوصفِ من الصدقِ الذي يُبنى عليه القرار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدقّةُ والأمانةُ في نقلِ الخبر."},"action":{"text":"تحرَّ الدقّةَ والأمانةَ في نقلِ الأخبارِ ووصفِ ما رأيت، فلا تزد ولا تنقص، كما وصف الهدهدُ ما رآه بدقّة؛ فالخبرُ الأمينُ أساسُ القرارِ الصائب؛ فتثبّت فيما تنقل، واجتنب المبالغةَ والتهويلَ والكذب، فالصدقُ في الروايةِ أمانةٌ يُحاسَب عليها."}},{"n":24,"reflection":{"text":"«وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطان أعمالهم فصدهم عن السبيل فهم لا يهتدون» — وجدتُها وقومَها يسجدون للشمسِ من دونِ الله، وزيّن لهم الشيطانُ أعمالهم فصدّهم عن سبيلِ الحقّ فهم لا يهتدون؛ ففي هذا خطرُ الشركِ وتزيينِ الشيطانِ للباطل؛ فاحذر أن يزيّن لك الشيطانُ باطلًا فتحسبه حقًّا، والزم عبادةَ الله وحده، فالشركُ ضلالٌ يصدّ عن السبيل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشركِ ومن تزيينِ الشيطانِ للباطل."},"action":{"text":"احذر الشركَ بكلِّ صوره، وأخلص السجودَ والعبادةَ لله وحده لا للشمسِ ولا لغيرها؛ واحذر أن يزيّن لك الشيطانُ باطلًا فتحسبه حقًّا فيصدّك عن السبيل؛ فتعاهد قلبك بالتوحيدِ الخالص، واعرض أعمالك على الشرعِ لا على استحسانك، فزينةُ الشيطانِ خدّاعة."}},{"n":25,"reflection":{"text":"«ألا يسجدوا لله الذي يخرج الخبء في السماوات والأرض ويعلم ما تخفون وما تعلنون» — زيّن لهم ذلك ألّا يسجدوا لله الذي يُخرج المخبوءَ في السماواتِ والأرضِ (كالغيثِ والنبات) ويعلم ما تُسرّون وما تُعلنون؛ ففي هذا أنّ المستحقَّ للسجودِ هو اللهُ العالمُ بالغيب؛ فاسجد لله وحده الذي يعلم سرَّك وعلنك، فمن أحاط علمه بكلِّ شيءٍ فهو وحده أهلٌ للعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عالم الغيب"],"heart_state":{"text":"إفرادُ الله بالسجودِ لعلمِه بالسرِّ والعلن."},"action":{"text":"أفرد الله بالسجودِ والعبادة، فهو الذي يُخرج المخبوءَ ويعلم سرَّك وعلانيتك؛ فاستحضر إحاطةَ علمِه بك في خلوتك وجلوتك، فيحملك ذلك على إخلاصِ العبادةِ له وحده، ومراقبتِه في السرِّ كالعلن؛ فمن علم أنّ الله يعلم خفاياه استحيا أن يعصيه."}},{"n":26,"reflection":{"text":"«الله لا إله إلا هو رب العرش العظيم» — الله لا معبودَ بحقٍّ إلا هو، ربُّ العرشِ العظيمِ الذي هو أعظمُ المخلوقات؛ ففي هذا تقريرُ التوحيدِ وعظمةِ الربّ؛ فوحّد الله ولا تعبد سواه، فهو ربُّ العرشِ العظيم، وما دونه أهونُ عليه، فأخلص له العبادةَ والتعظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب العرش العظيم"],"heart_state":{"text":"توحيدُ الله وتعظيمُه ربَّ العرشِ العظيم."},"action":{"text":"وحّد الله في عبادتك، فلا معبودَ بحقٍّ سواه، وهو ربُّ العرشِ العظيمِ الذي وسع الخلق؛ فعظّمه في قلبك حقَّ تعظيمه، وأخلص له العبادةَ والدعاءَ والخضوع؛ فمن استحضر عظمةَ ربِّ العرشِ صغُر في عينه كلُّ ما سواه، فأفرده بالتأله."}}]},{"title":"كتابُ سليمانَ إلى ملكةِ سبأ ومشورتُها","range":[27,35],"theme":"إرسالُ سليمانَ كتابَه مع الهدهد، وقراءةُ الملكةِ له ومشورتُها ملأها بحكمة، وإرسالُها الهديةَ اختبارًا","verses":[{"n":27,"reflection":{"text":"«قال سننظر أصدقت أم كنت من الكاذبين» — قال سليمانُ للهدهد: سنتثبّت أصدقتَ أم كنت من الكاذبين؛ ففي هذا التثبّتُ في الخبرِ قبل الحكم؛ فتثبّت من الأخبارِ قبل أن تبنيَ عليها حكمًا، فالعجلةُ في تصديقِ كلِّ خبرٍ بابُ خطأ، والتبيّنُ من الحكمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التثبّتُ في الخبرِ قبل الحكمِ عليه."},"action":{"text":"تثبّت من كلِّ خبرٍ يبلغك قبل أن تبنيَ عليه حكمًا أو تصرّفًا، كما قال سليمانُ «سننظر»؛ فلا تصدّق كلَّ ناقلٍ ولا تكذّبه بلا بيّنة؛ فالتبيّنُ عصمةٌ من الظلمِ والندم، والعجلةُ في القبولِ أو الردِّ مزلّة؛ فتحرَّ الصدقَ بالفحصِ والدليل."}},{"n":28,"reflection":{"text":"«اذهب بكتابي هذا فألقه إليهم ثم تول عنهم فانظر ماذا يرجعون» — اذهب بكتابي هذا فألقِه إليهم ثم تنحَّ عنهم فانظر ماذا يردّون؛ ففي هذا حسنُ تدبيرِ سليمانَ في دعوته؛ فأحسن تدبيرَ أمرك في الدعوةِ وغيرها، فالحكمةُ في اختيارِ الوسيلةِ والتمهّلِ لرؤيةِ النتيجة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"حسنُ التدبيرِ والحكمةِ في الدعوةِ والأمور."},"action":{"text":"أحسن تدبيرَ أمورك، واختر لها الوسائلَ الحكيمةَ كما دبّر سليمانُ إيصالَ كتابه ثم التنحّي لرؤيةِ الجواب؛ فلا تعالج الأمورَ بعجلةٍ ولا فوضى؛ فالتدبيرُ الحسنُ نصفُ النجاح، والحكمةُ ضالّةُ المؤمن؛ فخطّط لدعوتك وعملك بروِيّةٍ وبصيرة."}},{"n":29,"reflection":{"text":"«قالت يا أيها الملأ إني ألقي إلي كتاب كريم» — قالت الملكةُ: يا أيها الأشراف، إني أُلقِي إليّ كتابٌ كريمٌ عظيمُ الشأن؛ ففي هذا وصفُها للكتابِ بالكرمِ تعظيمًا؛ فاستشر أهلَ الرأيِ في المهمّات، وعظّم ما يستحقّ التعظيم، فحسنُ المشورةِ من رجاحةِ العقل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المشورةُ في المهمّاتِ وتعظيمُ ما يستحقّ."},"action":{"text":"استشر أهلَ الرأيِ والخبرةِ في أمورك المهمّة كما استشارت الملكةُ ملأها؛ ولا تستبدَّ برأيك؛ فالمشورةُ تكشف الصوابَ وتجمع القلوب؛ وعظّم ما يستحقّ التعظيمَ من الحقِّ وأهله؛ فرجاحةُ العقلِ تظهر في حسنِ التشاورِ وتقديرِ الأمورِ قدرها."}},{"n":30,"reflection":{"text":"«إنه من سليمان وإنه بسم الله الرحمن الرحيم» — إنّ الكتابَ من سليمانَ وإنه مفتتَحٌ ببسم الله الرحمن الرحيم؛ ففي هذا مشروعيّةُ افتتاحِ الكتبِ بالبسملة؛ فابدأ أمورك وكتبك باسمِ الله، فالبسملةُ بركةٌ وتوفيق، وبها تُستفتَح الأعمالُ اقتداءً بسليمانَ ونبيّنا ﷺ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن","الرحيم"],"heart_state":{"text":"افتتاحُ الأمورِ باسمِ الله وطلبُ بركته."},"action":{"text":"ابدأ كتبك وأعمالك ورسائلك باسمِ الله «بسم الله الرحمن الرحيم» كما فعل سليمان؛ فالتسميةُ بركةٌ واستعانةٌ بالله؛ واجعل ذكرَ الرحمنِ الرحيمِ حاضرًا في مفتتحِ شأنك؛ فمن بدأ باسمِ الله ورحمتِه رجا التوفيقَ والإعانة، والعملُ بلا تسميةٍ أبتر."}},{"n":31,"reflection":{"text":"«ألا تعلوا علي وأتوني مسلمين» — مضمونُ الكتاب: ألّا تتكبّروا عليّ وأتوني منقادين مسلمين؛ ففي هذا إيجازُ الدعوةِ إلى تركِ الكبرِ والانقيادِ للحقّ؛ فاترك الكبرَ عن الحقِّ وانقد له مسلمًا، فأصلُ الهلاكِ الاستكبار، وأصلُ النجاةِ الإسلامُ والانقياد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الكبرِ والانقيادُ للحقِّ مسلمًا."},"action":{"text":"اترك الكبرَ والاستعلاءَ عن قبولِ الحقّ، وانقد له مسلمًا مستسلمًا كما دعا سليمانُ سبأ؛ فالكبرُ أصلُ كلِّ هلاك، والإسلامُ والانقيادُ أصلُ كلِّ نجاة؛ فذلّل نفسك للحقِّ متى تبيّن، ولا يمنعك كبرٌ ولا هوًى من الإذعانِ لأمرِ الله."}},{"n":32,"reflection":{"text":"«قالت يا أيها الملأ أفتوني في أمري ما كنت قاطعة أمرا حتى تشهدون» — قالت: يا أيها الملأ أشيروا عليّ في أمري، ما كنت قاطعةً أمرًا حتى تحضروا وتشيروا؛ ففي هذا تواضعُها في المشورةِ وعدمُ الاستبداد؛ فشاور أهلَ الحلِّ والعقدِ ولا تستبدَّ برأيك، فالمستشيرُ لا يندم، والاستبدادُ بالرأيِ مزلّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التشاورُ وعدمُ الاستبدادِ بالرأي."},"action":{"text":"شاور أهلَ الرأيِ ولا تقطع أمرًا مهمًّا حتى تسمع مشورتهم كما فعلت الملكة؛ فالاستبدادُ بالرأيِ بابُ الخطأ والندم؛ فاجمع العقولَ على أمرك، فما ندم من استشار؛ وتواضع في طلبِ الرأيِ ممّن هم دونك، فالحكمةُ في جمعِ الآراءِ لا في الانفرادِ بها."}},{"n":33,"reflection":{"text":"«قالوا نحن أولو قوة وأولو بأس شديد والأمر إليك فانظري ماذا تأمرين» — قالوا: نحن أصحابُ قوّةٍ وبأسٍ شديد، والأمرُ إليك فانظري ماذا تأمرين؛ ففي هذا حسنُ أدبِ المستشارين وردُّ الأمرِ لصاحبِ القرار؛ فقدّم مشورتك بأدب، وردَّ القرارَ لأهله، فالمستشارُ ينصح ولا يفرض، ويجمع بين إبداءِ الرأيِ واحترامِ صاحبِ الأمر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أدبُ المشورة: النصحُ مع ردِّ القرارِ لأهله."},"action":{"text":"إذا استُشِرت فقدّم رأيك بأدبٍ ونصح، ثم ردَّ القرارَ إلى صاحبِ الأمر ولا تفرض عليه، كما قال ملأُ سبأ «والأمر إليك»؛ فالمستشارُ الأمينُ يبيّن وجهَ الصواب دون إلزام؛ فاجمع بين صدقِ النصيحةِ واحترامِ موقعِ من استشارك، فذلك من كمالِ العقلِ والأدب."}},{"n":34,"reflection":{"text":"«قالت إن الملوك إذا دخلوا قرية أفسدوها وجعلوا أعزة أهلها أذلة وكذلك يفعلون» — قالت: إنّ الملوكَ إذا دخلوا قريةً عنوةً أفسدوها وأذلّوا أعزّتها، وهكذا عادتهم؛ ففي هذا حكمتُها في تقديرِ العواقبِ وتجنّبِ الحرب؛ فقدّر عواقبَ أمورك قبل الإقدام، وآثِر السلمَ ما أمكن، فالحكيمُ ينظر في المآلاتِ لا في الحماسةِ العاجلة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديرُ العواقبِ وإيثارُ السلمِ ما أمكن."},"action":{"text":"انظر في عواقبِ أمورك ومآلاتها قبل الإقدام عليها كما فعلت ملكةُ سبأ حين قدّرت مفاسدَ الحرب؛ وآثِر الحلَّ السلميَّ ما دام ممكنًا؛ فالحكمةُ في وزنِ النتائجِ لا في الاندفاع؛ فلا تُقحم نفسك أو من تحتك في مهلكةٍ يمكن تجنّبها بالرويّةِ والتدبير."}},{"n":35,"reflection":{"text":"«وإني مرسلة إليهم بهدية فناظرة بم يرجع المرسلون» — وإني مرسلةٌ إليهم بهديةٍ لأختبرهم فأنظر بماذا يرجع الرسل؛ ففي هذا اختبارُها لسليمانَ أطالبُ ملكٍ أم داعٍ إلى الله؟ فتبصّر في مقاصدِ الناس، فالهديّةُ تُظهر أطامعٌ هو أم صاحبُ دعوة، والداعي الصادقُ لا تصرفه الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التبصّرُ في مقاصدِ الناسِ وامتحانُ الأمور."},"action":{"text":"تبصّر في مقاصدِ الناسِ واختبر الأمورَ قبل الحكمِ عليها كما اختبرت الملكةُ سليمانَ بالهدية؛ فبها يُعرَف طالبُ الدنيا من صاحبِ الدعوة؛ واعلم أنّ الداعيَ الصادقَ لا تصرفه الأموالُ عن الحقّ؛ فكن أنت ممّن لا تفتنه الهدايا عن مبدئه، ثابتًا على حقّك."}}]},{"title":"ردُّ الهديةِ وإحضارُ العرشِ وإسلامُ ملكةِ سبأ","range":[36,44],"theme":"ترفّعُ سليمانَ عن الهدية، وإحضارُ العرشِ بعلمٍ من الكتاب، وفطنةُ الملكةِ ودخولُها الصرحَ وإسلامُها لله ربِّ العالمين","verses":[{"n":36,"reflection":{"text":"«فلما جاء سليمان قال أتمدونن بمال فما آتاني الله خير مما آتاكم بل أنتم بهديتكم تفرحون» — فلما جاء الرسولُ سليمانَ قال: أتمدّونني بمالٍ؟ فما آتاني الله من النبوّةِ والملكِ خيرٌ ممّا آتاكم، بل أنتم بهديتكم تفرحون؛ ففي هذا زهدُ سليمانَ في الدنيا وترفّعُه عن المطامع؛ فاعلُ بهمّتك عن حطامِ الدنيا، فما عند الله خيرٌ وأبقى، والداعي لا تشتريه الأموال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الترفّعُ عن حطامِ الدنيا والزهدُ في المطامع."},"action":{"text":"ارفع همّتك عن حطامِ الدنيا وأعطياتِ الناسِ إذا أُريد بها صرفُك عن الحقّ، كما ترفّع سليمانُ عن هديةِ سبأ؛ فما عند الله خيرٌ وأبقى؛ فلا تفرح بالمالِ فرحَ من جعله غايته، ولا تبع دينك أو مبدأك بعرَضٍ زائل؛ فالغنى غنى النفس، وشرفُ الداعي في زهده."}},{"n":37,"reflection":{"text":"«ارجع إليهم فلنأتينهم بجنود لا قبل لهم بها ولنخرجنهم منها أذلة وهم صاغرون» — قال للرسول: ارجع إليهم، فلنأتينّهم بجنودٍ لا طاقةَ لهم بها، ولنخرجنّهم من بلدهم أذلّةً صاغرين إن لم يُسلموا؛ ففي هذا حزمُ سليمانَ بعد إقامةِ الحجّة؛ فبعد البيانِ يكون الحزم، فالداعي يبيّن الحقَّ ثم يأخذ بالقوّةِ في موضعها، والرفقُ لا يعني التفريطَ في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحزمُ في الحقِّ بعد إقامةِ البيان."},"action":{"text":"ابذل البيانَ والدعوةَ أولًا، فإذا لم ينفع مع القادرِ المعاندِ فخذ بالحزمِ في موضعه كما فعل سليمان؛ فالرفقُ في موضعه، والقوّةُ في موضعها؛ فلا تفرّط في الحقِّ باسمِ اللين، ولا تعجل بالقوّةِ قبل الحجّة؛ فالحكمةُ وضعُ كلِّ أمرٍ موضعه، والداعي حازمٌ حين يجب الحزم."}},{"n":38,"reflection":{"text":"«قال يا أيها الملأ أيكم يأتيني بعرشها قبل أن يأتوني مسلمين» — قال سليمانُ لأشرافِ قومه: أيّكم يأتيني بعرشِ الملكةِ قبل أن يأتوني منقادين مسلمين؛ ففي هذا إظهارُ آيةٍ لها تدعوها للإيمان؛ فاستعمل ما آتاك الله من قدرةٍ في الدعوةِ إلى الحقّ، وابتكر من الوسائلِ ما يليّن القلوبَ للإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توظيفُ القدرةِ والوسائلِ في الدعوةِ للحقّ."},"action":{"text":"وظّف ما آتاك الله من قدرةٍ ونفوذٍ في الدعوةِ إلى الحقِّ وتليينِ القلوب، كما استعمل سليمانُ إحضارَ العرشِ آيةً للملكة؛ فابتكر الوسائلَ الحكيمةَ التي تقرّب الناسَ من الإيمان؛ فالقوّةُ نعمةٌ تُشكَر بتسخيرها للخير، لا آلةَ بطشٍ ولا فخر؛ فاجعل قدرتك في خدمةِ الحق."}},{"n":39,"reflection":{"text":"«قال عفريت من الجن أنا آتيك به قبل أن تقوم من مقامك وإني عليه لقوي أمين» — قال عفريتٌ من الجنّ: أنا آتيك به قبل أن تقوم من مجلسك، وإني عليه لقويٌّ أمين؛ ففي هذا اجتماعُ القوّةِ والأمانةِ شرطًا للعمل؛ فاطلب في من توكّله القوّةَ والأمانةَ معًا، فبهما يتمّ العملُ ويُحفَظ، وأحدُهما دون الآخرِ نقص.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين القوّةِ والأمانةِ في اختيارِ العامل."},"action":{"text":"اطلب فيمن تُوكِله عملًا صفتي القوّةِ والأمانةِ معًا، فالقويُّ الخائنُ يضرّ، والأمينُ العاجزُ لا يُنجز، كما اقترن في وصفِ العفريتِ «لقوي أمين»؛ فوازن بين الكفاءةِ والنزاهةِ في اختيارك للأعوانِ والولايات؛ فبهاتين الصفتين تصلح الأعمالُ وتُؤدّى الأماناتُ حقّها."}},{"n":40,"reflection":{"text":"«قال الذي عنده علم من الكتاب أنا آتيك به قبل أن يرتد إليك طرفك فلما رآه مستقرا عنده قال هذا من فضل ربي ليبلوني أأشكر أم أكفر ومن شكر فإنما يشكر لنفسه ومن كفر فإن ربي غني كريم» — قال الذي عنده علمٌ من الكتاب: أنا آتيك به قبل أن يرتدَّ إليك بصرُك، فلما رآه مستقرًّا عنده قال: هذا من فضلِ ربّي ليختبرني أأشكر أم أكفر، ومن شكر فلنفسه، ومن كفر فربّي غنيٌّ كريم؛ ففي هذا أنّ النعمَ ابتلاءٌ بالشكر، وأنّ الله غنيٌّ عن شكرِنا؛ فاشكر النعمةَ ولا تنسبها لنفسك، فالشكرُ لك لا لله، وهو غنيٌّ كريم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغني","الكريم"],"heart_state":{"text":"استحضارُ أنّ النعمةَ ابتلاءٌ بالشكرِ لا فخر."},"action":{"text":"استحضر أنّ كلَّ نعمةٍ أنت فيها ابتلاءٌ لك: أتشكر أم تكفر؟ كقولِ العالمِ «ليبلوني أأشكر أم أكفر»؛ فانسب الفضلَ إلى الله لا إلى حولك وقوّتك؛ واعلم أنّ شكرك يعود نفعه إليك، والله غنيٌّ عنه كريمٌ بعطائه؛ فقابل كلَّ نعمةٍ بشكرٍ قوليٍّ وعمليٍّ يحفظها ويزيدها."}},{"n":41,"reflection":{"text":"«قال نكروا لها عرشها ننظر أتهتدي أم تكون من الذين لا يهتدون» — قال سليمانُ: غيّروا لها عرشها لننظر أتهتدي لمعرفته أم تكون من الذين لا يهتدون؛ ففي هذا اختبارُ عقلها وفطنتها؛ فاختبر الأمورَ بحكمةٍ لتعرف حقائقها، والفطنةُ نعمةٌ يُبتلى بها العبدُ أيهتدي بها إلى الحقِّ الأكبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختبارُ الأمورِ بحكمةٍ لمعرفةِ حقائقها."},"action":{"text":"استعمل الحكمةَ في اختبارِ الأمورِ والأشخاصِ لتعرف حقائقها كما اختبر سليمانُ فطنةَ الملكةِ بتنكيرِ عرشها؛ واجعل ما وهبك الله من ذكاءٍ وفطنةٍ سبيلًا للاهتداءِ إلى الحقِّ الأعظمِ لا للدنيا وحدها؛ فالعقلُ نعمةٌ يُسأل العبدُ عن توظيفها في معرفةِ ربّه وطاعته."}},{"n":42,"reflection":{"text":"«فلما جاءت قيل أهكذا عرشك قالت كأنه هو وأوتينا العلم من قبلها وكنا مسلمين» — فلما جاءت قيل لها: أهكذا عرشك؟ قالت: كأنه هو، وأوتينا العلمَ من قبلها وكنّا مسلمين؛ ففي هذا فطنتُها وحسنُ جوابها وتهيّؤُها للإسلام؛ فتلطّف في الجوابِ عند الاشتباه، وكن مهيّأً لقبولِ الحقِّ متى لاح، فالنفسُ المنصفةُ تسبق إلى الإسلامِ عند البرهان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفطنةُ في الجوابِ والتهيّؤُ لقبولِ الحق."},"action":{"text":"تحرَّ الدقّةَ والإنصافَ في جوابك عند الاشتباه فلا تجزم بما لا تتيقّنه، كقولِها «كأنه هو»؛ وهيّئ قلبك لقبولِ الحقِّ متى ظهر برهانه؛ فالنفسُ المنصفةُ المتهيّئةُ تسبق إلى الإسلامِ والانقياد؛ فاطلب الحقَّ بقلبٍ مفتوح، ولا يمنعك سابقُ حالٍ من الرجوعِ إليه."}},{"n":43,"reflection":{"text":"«وصدها ما كانت تعبد من دون الله إنها كانت من قوم كافرين» — ومنعها من الإسلامِ قبلُ ما كانت تعبده من دونِ الله، إنها كانت من قومٍ كافرين؛ ففي هذا أثرُ البيئةِ والعادةِ في الصدِّ عن الحقّ؛ فاحذر أن تصدّك العاداتُ الموروثةُ أو البيئةُ عن الحقّ، فكم حجب التقليدُ عن الهدى، فحرّر نفسك للحقِّ من أسرِ المألوف.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التحرّرُ من صدِّ العاداتِ والبيئةِ عن الحقّ."},"action":{"text":"احذر أن تصدّك العاداتُ الموروثةُ أو البيئةُ أو ما ألِفه قومك عن اتّباعِ الحقّ، كما صدّ ملكةَ سبأ ما كانت تعبد؛ فحرّر عقلك وقلبك من أسرِ التقليدِ الأعمى؛ ووازن ما نشأت عليه بميزانِ الوحي؛ فمن غلّب الحقَّ على المألوفِ هُدِي، ومن قدّم عادةَ آبائه ضلّ."}},{"n":44,"reflection":{"text":"«قيل لها ادخلي الصرح فلما رأته حسبته لجة وكشفت عن ساقيها قال إنه صرح ممرد من قوارير قالت رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين» — قيل لها: ادخلي القصر، فلما رأت أرضَه الزجاجيةَ حسبتها ماءً وكشفت عن ساقيها، فقال: إنه قصرٌ مبنيٌّ من زجاج، قالت: ربِّ إني ظلمتُ نفسي وأسلمتُ مع سليمانَ لله ربِّ العالمين؛ ففي هذا تمامُ إسلامها واعترافُها بظلمِ نفسها؛ فاعترف بتقصيرك وأسلم لله ربِّ العالمين، فالاعترافُ بالذنبِ بابُ التوبةِ والإسلامِ الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب العالمين"],"heart_state":{"text":"الاعترافُ بظلمِ النفسِ والإسلامُ لربِّ العالمين."},"action":{"text":"اعترف بتقصيرك وظلمك لنفسك، وأسلم وجهك لله ربِّ العالمين كما فعلت ملكةُ سبأ «رب إني ظلمت نفسي وأسلمت مع سليمان لله»؛ فالاعترافُ بالذنبِ أوّلُ التوبة، والإسلامُ الخالصُ غايةُ الهداية؛ فتُب إلى الله معترفًا، وجدّد إسلامك واستسلامك له كلَّ يوم، فالنجاةُ في الانقيادِ لربِّ العالمين."}}]},{"title":"صالحٌ مع ثمود: الدعوةُ والمكرُ والهلاك","range":[45,53],"theme":"دعوةُ صالحٍ إلى التوحيدِ والاستغفار، وإبطالُ التطيّر، ومكرُ التسعةِ الرهطِ ومكرُ الله بهم، ونجاةُ المؤمنين المتّقين","verses":[{"n":45,"reflection":{"text":"«ولقد أرسلنا إلى ثمود أخاهم صالحا أن اعبدوا الله فإذا هم فريقان يختصمون» — ولقد أرسلنا إلى ثمودَ أخاهم صالحًا أن اعبدوا الله وحده، فإذا هم فريقان: مؤمنٌ وكافرٌ يختصمون؛ ففي هذا أنّ الدعوةَ تفرّق الناسَ فريقين، وأنّ لبَّها التوحيد؛ فاجعل لبَّ دعوتك عبادةَ الله وحده، ولا يحزنك انقسامُ الناس، فتلك سنّةُ الدعواتِ مع الأنبياء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ التوحيدِ لبَّ الدعوةِ وعدمُ الحزنِ للانقسام."},"action":{"text":"اجعل عبادةَ الله وحده لبَّ دعوتك ومحورها كدعوةِ صالح «أن اعبدوا الله»؛ ولا يحزنك أن ينقسم الناسُ عندها إلى مصدّقٍ ومكذّب، فتلك سنّةُ الله في دعواتِ الرسل؛ فامضِ في تبليغِ التوحيدِ صابرًا، واعلم أنّ الحقَّ يميّز الصفوف، وليس عليك إلا البلاغ."}},{"n":46,"reflection":{"text":"«قال يا قوم لم تستعجلون بالسيئة قبل الحسنة لولا تستغفرون الله لعلكم ترحمون» — قال صالح: يا قوم لم تستعجلون العذابَ قبل الرحمة؟ هلّا تستغفرون الله لتُرحموا؛ ففي هذا دعوتُهم إلى الاستغفارِ بدل الاستعجالِ بالعذاب؛ فبادر بالاستغفارِ رجاءَ الرحمة، ولا تستعجل سوءًا، فالاستغفارُ يجلب الرحمةَ ويدفع البلاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاستغفارِ رجاءَ الرحمة."},"action":{"text":"بادر بالاستغفارِ من ذنوبك رجاءَ رحمةِ الله، ولا تستعجل الشرَّ أو تتحدّى العذابَ كما فعلت ثمود؛ فالاستغفارُ بابُ الرحمةِ ودافعُ البلاء «لولا تستغفرون الله لعلكم ترحمون»؛ فاجعل الاستغفارَ وِردًا لسانك وقلبك، فبه تُستنزَل الرحماتُ وتُدفَع النقمات، وتُمحى الخطايا."}},{"n":47,"reflection":{"text":"«قالوا اطيرنا بك وبمن معك قال طائركم عند الله بل أنتم قوم تفتنون» — قالوا: تشاءمنا بك وبمن معك، قال: سببُ شؤمكم مكتوبٌ عند الله بأعمالكم، بل أنتم قومٌ تُختبرون؛ ففي هذا إبطالُ التطيّرِ والتشاؤم؛ فلا تتطيّر ولا تتشاءم، فالخيرُ والشرُّ بقدرِ الله، والتطيّرُ وهمٌ يصدّ عن الحقّ، فتوكّل على الله واطرح الأوهام.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبطالُ التطيّرِ والتوكّلُ على الله."},"action":{"text":"اطرح التطيّرَ والتشاؤمَ بالأشخاصِ أو الأوقاتِ أو الأشياء، فما أصابك مقدّرٌ من الله لا من طِيَرَة، كما ردّ صالحٌ على قومه «طائركم عند الله»؛ فإذا وقع في نفسك شيءٌ من ذلك فامضِ متوكّلًا على الله غيرَ عابئٍ به؛ فالتوكّلُ يطرد الوهم، والتطيّرُ بابٌ من الشركِ يصدّ عن الحقّ."}},{"n":48,"reflection":{"text":"«وكان في المدينة تسعة رهط يفسدون في الأرض ولا يصلحون» — وكان في مدينةِ ثمودَ تسعةُ نفرٍ يفسدون في الأرضِ بالمعاصي ولا يصلحون؛ ففي هذا ذمُّ رؤوسِ الفسادِ الذين لا خيرَ فيهم؛ فاحذر أن تكون من المفسدين، وكن من المصلحين، فالناسُ صنفان: مصلحٌ ومفسد، فاختر أيَّ الفريقين تكون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإفسادِ والحرصُ على الإصلاح."},"action":{"text":"احذر أن تكون من المفسدين في الأرضِ بالمعاصي والظلمِ والإضرارِ بالناس، وكن من المصلحين الذين يعمرون الأرضَ بالطاعةِ والنفع؛ فالله ذمَّ التسعةَ «يفسدون في الأرض ولا يصلحون»؛ فوازن نفسك: أمصلحٌ أنت أم مفسد؟ واسعَ في الإصلاحِ ما استطعت، ودع الإفسادَ كلَّه."}},{"n":49,"reflection":{"text":"«قالوا تقاسموا بالله لنبيتنه وأهله ثم لنقولن لوليه ما شهدنا مهلك أهله وإنا لصادقون» — قالوا: تحالفوا بالله لنقتلنّه وأهله ليلًا ثم لنقولنّ لوليّه: ما حضرنا هلاكهم وإنا لصادقون؛ ففي هذا جمعُهم بين الغدرِ والكذبِ والحلفِ الكاذب؛ فاحذر أن تجعل اسمَ الله غطاءً لمكرٍ وكذب، فالحلفُ على الباطلِ من أعظمِ الجرأةِ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من اتّخاذِ الحلفِ باللهِ غطاءً للباطل."},"action":{"text":"احذر أن تحلف بالله على باطلٍ أو تجعل اسمه غطاءً لمكرٍ أو كذبٍ أو غدرٍ كما فعل المفسدون في ثمود؛ فالحلفُ الكاذبُ واستغلالُ اسمِ الله في الإثمِ من أعظمِ الجرأةِ عليه؛ فعظّم اسمَ الله فلا تحلف به إلا صادقًا في حقّ، ونزّه لسانك عن اليمينِ الغموسِ وأنواعِ الغدر."}},{"n":50,"reflection":{"text":"«ومكروا مكرا ومكرنا مكرا وهم لا يشعرون» — ومكروا بصالحٍ ومن معه مكرًا، ومكرنا بهم مكرًا (جزاءً) وهم لا يشعرون؛ ففي هذا أنّ مكرَ الله بالماكرين أشدّ، وأنه يأتيهم من حيث لا يحتسبون؛ فلا تأمن مكرَ الله إن مكرت بأوليائه، فمكرُه غالبٌ خفيّ، والعاقبةُ لأهلِ الحقّ لا للماكرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من مكرِ الله بالماكرين على أوليائه."},"action":{"text":"لا تمكر بأولياءِ الله وأهلِ الحقّ، ولا تأمن مكرَ الله إن بغيتَ عليهم، فمكرُه بالماكرين أشدُّ وأخفى «ومكروا مكرا ومكرنا مكرا»؛ فمن كاد للحقِّ كاده الله من حيث لا يشعر؛ فاجعل خوفك من الله رادعًا لك عن البغيِ والكيد؛ فالعاقبةُ للحقِّ وأهله، والخذلانُ مصيرُ الماكرين."}},{"n":51,"reflection":{"text":"«فانظر كيف كان عاقبة مكرهم أنا دمرناهم وقومهم أجمعين» — فانظر كيف كانت عاقبةُ مكرهم أنا دمّرناهم وقومهم أجمعين؛ ففي هذا أنّ عاقبةَ المكرِ بالحقِّ الهلاك؛ فاعتبر بعاقبةِ الماكرين، واعلم أنّ من حفر لأخيه حفرةً وقع فيها، فالبغيُ مصرعُ صاحبه، والمكرُ يعود على أهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بأنّ عاقبةَ المكرِ الهلاك."},"action":{"text":"اعتبر بأنّ عاقبةَ المكرِ بالحقِّ وأهلِه الدمارُ والهلاك «أنا دمرناهم وقومهم أجمعين»؛ فلا تبغِ على أحدٍ ولا تمكر، فالبغيُ مصرعُ صاحبه، والمكرُ السيّئُ لا يحيق إلا بأهله؛ فاسلك سبيلَ الاستقامةِ لا الكيد؛ فمن نجا من عقوبةِ الدنيا لم ينجُ من عقوبةِ الآخرة، والله بالمرصاد."}},{"n":52,"reflection":{"text":"«فتلك بيوتهم خاوية بما ظلموا إن في ذلك لآية لقوم يعلمون» — فتلك بيوتهم خاليةٌ خرابٌ بسببِ ظلمهم، إنّ في ذلك لعبرةً لقومٍ يعلمون؛ ففي هذا أنّ آثارَ الهالكين عبرةٌ لأهلِ العلم؛ فاعتبر بمصارعِ الظالمين، فالظلمُ يخرّب الديار، والعلمُ الحقُّ ما أثمر عبرةً وخشية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الظالمين وأثرِ الظلم."},"action":{"text":"اعتبر بآثارِ الأممِ الظالمةِ ومصارعهم، فبيوتُهم الخاويةُ آيةٌ على أنّ الظلمَ يخرّب الديارَ ويهلك أهلها «خاوية بما ظلموا»؛ فاحذر الظلمَ كلَّه، واجعل من أخبارِ الهالكين عبرةً تزيدك خشيةً لله؛ فالعلمُ النافعُ ما حملك على الاتّعاظِ والعمل، لا مجرّدُ المعرفةِ بلا أثر."}},{"n":53,"reflection":{"text":"«وأنجينا الذين آمنوا وكانوا يتقون» — وأنجينا الذين آمنوا وكانوا يتّقون الله؛ ففي هذا أنّ الإيمانَ والتقوى سببُ النجاة؛ فالزم الإيمانَ والتقوى تنجُ من المهالك، فالله ينجّي أولياءه المتّقين، ويهلك المكذّبين، فاجعل نجاتك في تقواك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ والتقوى سببُ النجاةِ من المهالك."},"action":{"text":"الزم الإيمانَ والتقوى، فبهما تنجو من المهالكِ في الدنيا والآخرة كما نجّى الله المؤمنين المتّقين من قومِ صالح؛ فحقّق التقوى بفعلِ الأوامرِ واجتنابِ النواهي؛ فمن اتّقى الله جعل له مخرجًا ونجاةً؛ فاجعل تقوى الله حصنك وملاذك، فهي سببُ النجاةِ حين يهلك الظالمون."}}]},{"title":"لوطٌ مع قومه: الفاحشةُ والنجاةُ والعذاب","range":[54,58],"theme":"إنكارُ لوطٍ الفاحشةَ على قومه، وعداؤهم لأهلِ الطهر، ونجاةُ لوطٍ وأهلِه إلا امرأتَه، وإمطارُ العذابِ عليهم","verses":[{"n":54,"reflection":{"text":"«ولوطا إذ قال لقومه أتأتون الفاحشة وأنتم تبصرون» — واذكر لوطًا إذ قال لقومه: أتأتون الفاحشةَ وأنتم تعلمون قبحها؟ ففي هذا إنكارُ لوطٍ للفاحشةِ مع علمهم بقبحها؛ فاجتنب الفواحشَ لا سيّما ما عُلِم قبحه، فارتكابُ المنكرِ مع العلمِ بقبحه أعظمُ جرمًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الفواحشِ لا سيّما ما عُلِم قبحه."},"action":{"text":"اجتنب الفواحشَ والمنكراتِ كلَّها، وخاصّةً ما تعلم قبحه علمَ يقين، فإنّ اقترافَ القبيحِ مع العلمِ بقبحه أعظمُ إثمًا كإنكارِ لوط «وأنتم تبصرون»؛ فلا تجعل معرفتك بالحرامِ حجّةً عليك بمواقعته؛ بل ليكن علمك بالقبحِ زاجرًا لك عنه، فالعلمُ حجّةٌ لك إن عملت، وعليك إن خالفت."}},{"n":55,"reflection":{"text":"«أئنكم لتأتون الرجال شهوة من دون النساء بل أنتم قوم تجهلون» — أإنكم لتأتون الرجالَ شهوةً من دونِ النساء؟ بل أنتم قومٌ تجهلون عاقبةَ فعلكم؛ ففي هذا تقبيحُ فعلتهم ووصفُهم بالجهل؛ فاعلم أنّ مخالفةَ الفطرةِ والشرعِ جهلٌ وإن ظنّه صاحبه علمًا، فالحكمةُ في اتّباعِ الفطرةِ السليمةِ وشرعِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ مخالفةَ الفطرةِ والشرعِ جهل."},"action":{"text":"اعلم أنّ كلَّ ما خالف الفطرةَ السليمةَ وشرعَ الله فهو جهلٌ وسفهٌ وإن زيّنه أهلُه، كفعلِ قومِ لوط «بل أنتم قوم تجهلون»؛ فالزم ما فطرك الله عليه وشرعه لك، ولا تنخدع بتزيينِ المنكرِ باسمِ الحرّيةِ أو التقدّم؛ فالعلمُ الحقُّ موافقةُ الفطرةِ والوحي، والجهلُ مخالفتهما."}},{"n":56,"reflection":{"text":"«فما كان جواب قومه إلا أن قالوا أخرجوا آل لوط من قريتكم إنهم أناس يتطهرون» — فما كان جوابُ قومه إلا أن قالوا: أخرجوا آلَ لوطٍ من قريتكم، إنهم أناسٌ يتنزّهون عن فعلنا؛ ففي هذا أنّ الفاسدَ يعادي أهلَ الطهرِ ويسخر منهم؛ فلا يهزّك استهزاءُ الفاسدين بطهرك، فالعزّةُ في الطهارةِ والعفّة، وعداوةُ الفاسدين شهادةٌ لك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الطهرِ رغمَ عداءِ الفاسدين."},"action":{"text":"اثبت على طهرك وعفّتك ولو عاداك الفاسدون وسخروا منك ونبذوك كما فعل قومُ لوطٍ بأهله «إنهم أناس يتطهرون»؛ فلا يهزّك استهزاءُ أهلِ الباطل، بل اجعل عداوتهم لك على طهرك شرفًا وشهادة؛ فالعزّةُ الحقّةُ في العفّةِ والاستقامة، لا في مجاراةِ الفسّاقِ خوفَ لومهم."}},{"n":57,"reflection":{"text":"«فأنجيناه وأهله إلا امرأته قدرناها من الغابرين» — فأنجينا لوطًا وأهله إلا امرأته قدّرنا أنها من الباقين في العذاب؛ ففي هذا أنّ القرابةَ لا تنفع مع الكفر، وأنّ النجاةَ بالإيمانِ لا بالنسب؛ فلا تتّكل على قرابةٍ أو نسب، فامرأةُ النبيِّ هلكت بكفرها، والنجاةُ بالعملِ الصالحِ لا بالأنساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أنّ النجاةَ بالإيمانِ والعملِ لا بالنسب."},"action":{"text":"اعلم أنّ النجاةَ عند الله بالإيمانِ والعملِ الصالحِ لا بالقرابةِ والنسب، فامرأةُ لوطٍ هلكت مع أنها زوجُ نبيٍّ لأنها كفرت «إلا امرأته قدرناها من الغابرين»؛ فلا تتّكل على شرفِ نسبٍ أو صلةِ قرابة؛ بل اعمل لنجاتك بنفسك، فكلٌّ مرهونٌ بعمله، ولا يغني أحدٌ عن أحدٍ شيئًا."}},{"n":58,"reflection":{"text":"«وأمطرنا عليهم مطرا فساء مطر المنذرين» — وأمطرنا عليهم حجارةً من العذاب، فبئس مطرُ المنذَرين الذين لم يتّعظوا؛ ففي هذا عاقبةُ من أُنذِر فلم ينتهِ؛ فاتّعظ بالنذارةِ قبل نزولِ العذاب، فمن لم تنفعه المواعظُ حلّ به ما حلّ بقومِ لوط، والسعيدُ من وُعِظ بغيره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بالنذارةِ قبل نزولِ العذاب."},"action":{"text":"اتّعظ بنُذُرِ الله ومواعظه قبل أن ينزل بك العذاب، فلا تكن من المنذَرين الذين لم ينفعهم الإنذار فأُهلكوا «فساء مطر المنذرين»؛ فالسعيدُ من اتّعظ بغيره، والشقيُّ من لم تردعه النذر؛ فبادر بالتوبةِ والاستقامةِ عند سماعِ الموعظة، ولا تسوّف حتى يفاجئك ما لا مردَّ له."}}]},{"title":"براهينُ التوحيدِ: أمّن خلق ودبّر ويجيب المضطر","range":[59,66],"theme":"حمدُ الله والتسليمُ على أصفيائه، وسلسلةُ «أمّن» الدالّةِ على تفرّدِ الله بالخلقِ والتدبيرِ وإجابةِ المضطرِّ وعلمِ الغيب، وحيرةُ منكري البعث","verses":[{"n":59,"reflection":{"text":"«قل الحمد لله وسلام على عباده الذين اصطفى آلله خير أما يشركون» — قل: الحمدُ لله وسلامٌ على عباده الذين اختارهم (الأنبياء)، أالله خيرٌ أم ما يشركون به؟ ففي هذا حمدُ الله والتسليمُ على أصفيائه، وإقامةُ الحجّةِ على المشركين؛ فاحمد الله وسلّم على أنبيائه، واعلم أنّ الله خيرٌ من كلِّ معبودٍ سواه، فأخلص له الحمدَ والعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حمدُ الله والإقرارُ بأنه خيرٌ من كلِّ معبود."},"action":{"text":"أكثر من حمدِ الله والثناءِ عليه، وسلّم على عباده الذين اصطفى من الأنبياءِ والصالحين؛ وأيقن أنّ الله خيرٌ من كلِّ ما يُعبَد سواه، فلا يستحقّ الحمدَ والعبادةَ إلا هو؛ فأخلص له حمدك وعبادتك، وقايس بين ما عنده وما عند غيره، فلا نسبةَ بين الخالقِ والمخلوق."}},{"n":60,"reflection":{"text":"«أمن خلق السماوات والأرض وأنزل لكم من السماء ماء فأنبتنا به حدائق ذات بهجة ما كان لكم أن تنبتوا شجرها أإله مع الله بل هم قوم يعدلون» — بل أمَن خلق السماواتِ والأرضَ وأنزل الماءَ فأنبت به حدائقَ بهيّةً لا تقدرون على إنباتِ شجرها؟ أمعبودٌ مع الله؟ بل هم قومٌ يعدلون به غيرَه؛ ففي هذا إقامةُ التوحيدِ ببديعِ الخلق؛ فتأمّل آياتِ الله في الخلقِ والنبات، فمن انفرد بالخلقِ انفرد باستحقاقِ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ ببديعِ الخلقِ على وحدانيةِ الخالق."},"action":{"text":"تأمّل آياتِ الله في خلقِ السماواتِ والأرضِ وإنزالِ الماءِ وإنباتِ الحدائقِ البهيّة، واستدلَّ بها على أنّ الخالقَ المنعمَ هو وحده المستحقُّ للعبادة؛ فمن عجز الناسُ عن إنباتِ شجرةٍ كيف يُعبَد سواه؟ فأفرد الله بالعبادةِ كما انفرد بالخلقِ والإنعام، ولا تعدل به شيئًا من خلقه."}},{"n":61,"reflection":{"text":"«أمن جعل الأرض قرارا وجعل خلالها أنهارا وجعل لها رواسي وجعل بين البحرين حاجزا أإله مع الله بل أكثرهم لا يعلمون» — بل أمَن جعل الأرضَ مستقرًّا وشقّ فيها الأنهارَ وأرسى الجبالَ وحجز بين العذبِ والملح؟ أمعبودٌ مع الله؟ بل أكثرهم لا يعلمون؛ ففي هذا آياتُ القدرةِ في تدبيرِ الأرض؛ فتأمّل نظامَ الأرضِ وإحكامَه، فمن دبّر هذا الكونَ بحكمةٍ هو وحده الإله، وجهلُ الأكثرين لا يقدح في الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تدبيرِ الأرضِ دليلًا على التوحيد."},"action":{"text":"تأمّل كيف جعل الله الأرضَ قرارًا مستقرًّا، وأجرى فيها الأنهار، وأرسى الجبال، وحجز بين البحرين؛ فاستدلَّ بهذا الإحكامِ على وحدانيةِ مدبّره ومستحقِّ عبادته؛ ولا يغرّنك أنّ أكثرَ الناسِ لا يعلمون هذا الحقّ، فالحقُّ لا يُعرَف بالكثرة؛ فكن من القلّةِ العالمةِ الموحّدةِ العابدةِ لله وحده."}},{"n":62,"reflection":{"text":"«أمن يجيب المضطر إذا دعاه ويكشف السوء ويجعلكم خلفاء الأرض أإله مع الله قليلا ما تذكرون» — بل أمَن يجيب المضطرَّ إذا دعاه ويكشف الضرَّ ويجعلكم خلفاءَ في الأرض؟ أمعبودٌ مع الله؟ قليلًا ما تتذكّرون؛ ففي هذا أعظمُ برهانٍ: إجابةُ المضطرِّ وكشفُ السوء؛ فالجأ إلى الله في اضطرارك، فهو وحده مجيبُ الدعاءِ كاشفُ الكرب، ومن جرّب إجابته أيقن أنه لا إله سواه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["المجيب"],"heart_state":{"text":"اللجوءُ إلى اللهِ مجيبِ المضطرِّ كاشفِ السوء."},"action":{"text":"الجأ إلى الله وحده في كلِّ اضطرارٍ وشدّةٍ وكربٍ، وادعُه موقنًا بالإجابة، فهو الذي يجيب المضطرَّ إذا دعاه ويكشف السوء؛ ولا تعلّق قلبك بسواه؛ فاستحضر هذه الآيةَ عند كلِّ ضيق، واصدق في اللجوءِ إليه؛ فمن ذاق حلاوةَ إجابةِ الله له في اضطراره عرف أنه لا مفزعَ ولا إله سواه."}},{"n":63,"reflection":{"text":"«أمن يهديكم في ظلمات البر والبحر ومن يرسل الرياح بشرا بين يدي رحمته أإله مع الله تعالى الله عما يشركون» — بل أمَن يهديكم في ظلماتِ البرِّ والبحرِ بالنجومِ والعلامات، ويرسل الرياحَ مبشّراتٍ قبل المطر؟ أمعبودٌ مع الله؟ تنزّه الله عمّا يشركون؛ ففي هذا هدايتُه في الظلماتِ وإرسالُه الرياح؛ فاعرف نعمةَ الله في هدايتك وأسبابِ حياتك، ونزّهه عن الشركاء، فهو المتفرّدُ بالإنعامِ والتدبير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ هدايةِ الله وتنزيهُه عن الشركاء."},"action":{"text":"اعرف نعمةَ الله في هدايتك سبلَ البرِّ والبحرِ في الظلمات، وفي إرساله الرياحَ بشرى برحمته؛ فاشكره على هذه النعم، ونزّهه عن كلِّ شريك؛ فمن انفرد بالهدايةِ والإنعامِ والتدبيرِ تعالى أن يكون له شريك؛ فوحّده في العبادةِ كما تفرّد في الربوبية، وسبّحه عمّا يصفه المشركون."}},{"n":64,"reflection":{"text":"«أمن يبدأ الخلق ثم يعيده ومن يرزقكم من السماء والأرض أإله مع الله قل هاتوا برهانكم إن كنتم صادقين» — بل أمَن يبدأ الخلقَ ثم يعيده بعد الموت، ومن يرزقكم من السماءِ والأرض؟ أمعبودٌ مع الله؟ قل هاتوا حجّتكم إن كنتم صادقين في شرككم؛ ففي هذا برهانُ البدءِ والإعادةِ والرزق، وتحدّي المشركين بالبرهان؛ فأيقن بأنّ من بدأ الخلقَ قادرٌ على إعادته، واطلب البرهانَ لكلِّ دعوى، فالحقُّ ما قام عليه الدليل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ وطلبُ البرهانِ لكلِّ دعوى."},"action":{"text":"أيقن بأنّ الله الذي بدأ الخلقَ قادرٌ على إعادته وبعثه، وأنه وحده الرازقُ من السماءِ والأرض؛ فلا تشكّ في البعث، ولا تعبد سواه؛ واطلب البرهانَ على كلِّ دعوى تُلقى إليك «قل هاتوا برهانكم»؛ فلا تقبل قولًا بلا دليل، ولا تعتقد إلا ما قام عليه الحقّ؛ فدينُك مبنيٌّ على البرهانِ لا التقليد."}},{"n":65,"reflection":{"text":"«قل لا يعلم من في السماوات والأرض الغيب إلا الله وما يشعرون أيان يبعثون» — قل: لا يعلم من في السماواتِ والأرضِ الغيبَ إلا الله، وما يدرون متى يُبعثون؛ ففي هذا اختصاصُ الله بعلمِ الغيب؛ فاعتقد أنّ الغيبَ لله وحده، فلا تصدّق مدّعيَ علمِه من كاهنٍ أو منجّم، وسلّم أمرَ الغيبِ لعالمه سبحانه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["عالم الغيب"],"heart_state":{"text":"الإيمانُ باختصاصِ الله بعلمِ الغيب."},"action":{"text":"اعتقد جازمًا أنّ الغيبَ لا يعلمه إلا الله وحده، لا مَلَكٌ مقرّبٌ ولا نبيٌّ مرسلٌ إلا بما أعلمه الله؛ فلا تصدّق كاهنًا ولا عرّافًا ولا منجّمًا يدّعي علمَ الغيب؛ وسلّم أمرَ المستقبلِ والأقدارِ لعالمِ الغيبِ سبحانه؛ فمن أفرد الله بعلمِ الغيبِ استراح قلبه، ولم يعلّق رجاءه بمدّعٍ كاذب."}},{"n":66,"reflection":{"text":"«بل ادارك علمهم في الآخرة بل هم في شك منها بل هم منها عمون» — بل تلاحق علمُهم وعجز عن إدراكِ حقيقةِ الآخرة، بل هم في شكٍّ منها، بل هم عنها عَمُون؛ ففي هذا وصفُ حيرةِ المكذّبين بالآخرة؛ فاحذر الشكَّ في الآخرةِ والعمى عنها، ورسّخ يقينك بها، فالشكُّ فيها عمًى يقود إلى الخسران.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"ترسيخُ اليقينِ بالآخرةِ والحذرُ من الشكِّ فيها."},"action":{"text":"رسّخ يقينك باليومِ الآخرِ والبعثِ والحساب، واحذر أن تقع في شكٍّ منها أو عمًى عنها كحالِ المكذّبين «بل هم منها عمون»؛ فالشكُّ في الآخرةِ يفسد العمل، واليقينُ بها يقوّمه؛ فاستحضرها دائمًا، وأكثر من ذكرِ الموتِ وما بعده؛ فمن أيقن بالدارِ الآخرةِ عمل لها، ومن عمِي عنها آثر الفانيةَ فخسر."}}]},{"title":"شبهةُ البعثِ والردُّ عليها وتسليةُ النبيّ","range":[67,75],"theme":"استبعادُ الكفارِ للبعث، والأمرُ بالسيرِ للاعتبار، وتسليةُ النبيِّ ونهيُه عن الحزن، وسعةُ فضلِ الله وإحاطةُ علمِه بالسرِّ والعلن","verses":[{"n":67,"reflection":{"text":"«وقال الذين كفروا أإذا كنا ترابا وآباؤنا أئنا لمخرجون» — وقال الكفار: أإذا صرنا ترابًا نحن وآباؤنا أإنا لمُخرَجون أحياءً؟ ففي هذا استبعادُهم البعثَ واستنكارُهم له؛ فلا يدخلك استبعادُ الجاهلين للبعثِ شكًّا، فمن أنشأ الخلقَ أولًا قادرٌ على إعادته، واستبعادُ البعثِ جهلٌ بقدرةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دفعُ استبعادِ البعثِ باليقينِ بقدرةِ الله."},"action":{"text":"لا يدخلنّ قلبك شيءٌ من استبعادِ الكافرين للبعثِ واستنكارهم له؛ فمن خلقك من ترابٍ أولًا قادرٌ على إعادتك بعد أن تصير ترابًا؛ فرسّخ إيمانك بقدرةِ الله على البعث، ورُدَّ شبهةَ المستبعدين بالتأمّلِ في بدءِ الخلق؛ فالإعادةُ أهونُ من البدء، وكلاهما على الله يسير؛ فاستعدَّ ليومِ الخروج."}},{"n":68,"reflection":{"text":"«لقد وعدنا هذا نحن وآباؤنا من قبل إن هذا إلا أساطير الأولين» — قالوا: لقد وُعِدنا البعثَ نحن وآباؤنا من قبلُ فلم نره، ما هذا إلا أكاذيبُ الأوّلين؛ ففي هذا تكذيبُهم بوعدِ الله بحجّةِ التأخّر؛ فلا يغرّنك تأخّرُ وعدِ الله، فوعدُه حقٌّ آتٍ في وقته، وتكذيبُ الحقِّ بدعوى أنه أساطيرُ من صنيعِ المعاندين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بوعدِ الله وإن تأخّر تحقّقه."},"action":{"text":"لا يغرّنك تأخّرُ وعدِ الله بالبعثِ أو غيره، فوعدُه حقٌّ لا يتخلّف، يقع في وقته المقدّر؛ ولا تجعل تأخّرَ الشيءِ حجّةً على إنكاره كما فعل الكفار «إن هذا إلا أساطير الأولين»؛ فثِق بوعدِ ربّك، واعمل لما وعد به من حسابٍ وجزاء؛ فالمكذّبُ يهزأ اليومَ ويندم غدًا، والمؤمنُ يستعدّ فيربح."}},{"n":69,"reflection":{"text":"«قل سيروا في الأرض فانظروا كيف كان عاقبة المجرمين» — قل لهم: سيروا في الأرضِ فانظروا كيف كانت عاقبةُ المجرمين المكذّبين قبلكم؛ ففي هذا الأمرُ بالاعتبارِ بمصارعِ الأمم؛ فسِر في الأرضِ معتبرًا لا لاهيًا، وتأمّل عواقبَ المكذّبين لتزداد يقينًا وخشية، فالتاريخُ عظةٌ لمن اعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ المكذّبين عند السيرِ في الأرض."},"action":{"text":"إذا سِرت في الأرضِ أو قرأت أخبارَ الأمم، فاجعل نظرك نظرَ اعتبارٍ لا نظرَ لهوٍ وسياحة؛ وتأمّل كيف كانت عاقبةُ المجرمين المكذّبين، فديارُهم شاهدةٌ على هلاكهم؛ فليزدك ذلك يقينًا بوعدِ الله وخشيةً من عقابه؛ فمن اعتبر بغيره سلم، والتاريخُ موعظةٌ لأولي الأبصار."}},{"n":70,"reflection":{"text":"«ولا تحزن عليهم ولا تكن في ضيق مما يمكرون» — ولا تحزن يا محمدُ على إعراضهم، ولا تكن في ضيقٍ من مكرهم؛ ففي هذا تسليةُ النبيِّ ﷺ وأمرُه بطرحِ الحزنِ والضيق؛ فلا تحزن على من أعرض عن الحقِّ بعد بلاغك، ولا يضق صدرك بمكرِ الأعداء، فالله كافيك، وحسبك التوكّلُ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طرحُ الحزنِ والضيقِ والتوكّلُ على الله."},"action":{"text":"لا تحمل همَّ من أعرض عن الحقِّ بعد أن بلّغته، ولا تحزن على هدايتهم فليس ذلك إليك؛ ولا يضق صدرك بمكرِ الأعداءِ وكيدهم، فالله عاصمك وكافيك؛ فادفع الحزنَ بالرضا بقدرِ الله، وادفع الضيقَ بالتوكّلِ عليه؛ فمن فوّض أمره إلى الله كفاه همّه، وأبدله بالضيقِ سعةً، وبالحزنِ طمأنينة."}},{"n":71,"reflection":{"text":"«ويقولون متى هذا الوعد إن كنتم صادقين» — ويقولون: متى يقع هذا الوعدُ بالبعثِ أو العذابِ إن كنتم صادقين؟ ففي هذا استعجالُهم استهزاءً وتكذيبًا؛ فلا يستفزّنك استعجالُ المستهزئين، فوقتُ الوعدِ بيدِ الله، والاستعجالُ به حمقٌ وجهلٌ بحكمةِ التأجيل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاكتراثِ باستعجالِ المستهزئين للوعد."},"action":{"text":"لا يستفزّنك استعجالُ المكذّبين للوعدِ بالعذابِ أو البعثِ على وجهِ الاستهزاء «متى هذا الوعد»؛ فوقتُ وقوعه بيدِ الله وحده بحكمته؛ فلا تتعجّل أنت، ولا تضطرب لتعجّلهم؛ بل امضِ في الحقّ، وكِل الأمرَ إلى الله؛ فالمستعجلُ بالعذابِ جاهلٌ بأنّ في تأخيره حكمةً وإمهالًا، وأنّ ما هو آتٍ قريب."}},{"n":72,"reflection":{"text":"«قل عسى أن يكون ردف لكم بعض الذي تستعجلون» — قل: لعلّه قد قرب واقترب لكم بعضُ الذي تستعجلون به من العذاب؛ ففي هذا تحذيرُهم من قربِ ما يستعجلون؛ فلا تأمن قربَ ما تستعجله من الشرّ، فقد يكون العذابُ أقربَ ممّا تظنّ، فبادر بالتوبةِ قبل أن يحلَّ ما استعجلت.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قربِ العذابِ والمبادرةُ بالتوبة."},"action":{"text":"لا تأمن أن يكون ما تستبعده أو تستعجله من العذابِ قريبًا منك «عسى أن يكون ردف لكم بعض الذي تستعجلون»؛ فبادر بالتوبةِ والاستعدادِ قبل أن يفاجئك ما لا مردَّ له؛ فقربُ الأجلِ والعذابِ مستور، والغافلُ يحسبه بعيدًا وهو قريب؛ فكن على حذرٍ دائمٍ، متأهّبًا بالطاعةِ، لا مغترًّا بالإمهال."}},{"n":73,"reflection":{"text":"«وإن ربك لذو فضل على الناس ولكن أكثرهم لا يشكرون» — وإنّ ربّك لصاحبُ فضلٍ عظيمٍ على الناسِ بالنعمِ والإمهال، ولكنّ أكثرهم لا يشكرون؛ ففي هذا سعةُ فضلِ الله وقلّةُ الشاكرين؛ فكن من القلّةِ الشاكرة، واعرف فضلَ الله عليك في كلِّ نعمة، فالشكرُ يحفظ النعمَ ويزيدها، والغفلةُ عنه كفرانٌ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشكرُ لفضلِ الله والكونُ من القلّةِ الشاكرة."},"action":{"text":"اعرف عظيمَ فضلِ الله عليك في نعمِه الظاهرةِ والباطنةِ وفي إمهاله لك؛ وكن من القلّةِ الشاكرةِ لا من الأكثرِ الغافل «ولكن أكثرهم لا يشكرون»؛ فاشكر الله بقلبك ولسانك وجوارحك؛ فالشكرُ قيدُ النعمِ الموجودةِ وصيدُ المفقودة؛ ومن عرف فضلَ الله عليه استحيا أن يقابله بالمعصيةِ والجحود."}},{"n":74,"reflection":{"text":"«وإن ربك ليعلم ما تكن صدورهم وما يعلنون» — وإنّ ربّك ليعلم ما تخفيه صدورُهم وما يظهرونه؛ ففي هذا إحاطةُ علمِ الله بالسرِّ والعلن؛ فراقب الله في سرّك كما في علنك، فهو يعلم خفايا صدرك، فطهّر قلبك من الغلِّ والحسدِ والرياء، فعالمُ السرِّ لا يخفى عليه شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"مراقبةُ الله العالمِ بالسرِّ والعلنِ وتطهيرُ القلب."},"action":{"text":"راقب الله في سريرتك كما تراقبه في علانيتك، فهو يعلم ما تُكنّه صدورُك وما تُعلنه؛ فطهّر قلبك من الغلِّ والحسدِ والحقدِ والرياءِ والنيّاتِ الفاسدة؛ فمن أيقن أنّ الله يعلم خفايا صدره، اجتهد في إصلاحِ باطنه كظاهره؛ فالعبرةُ بصلاحِ القلب، وعالمُ الغيبِ لا تخفى عليه خافية."}},{"n":75,"reflection":{"text":"«وما من غائبة في السماء والأرض إلا في كتاب مبين» — وما من خفيّةٍ في السماءِ والأرضِ إلا وهي مثبتةٌ في كتابٍ مبين (اللوحِ المحفوظ)؛ ففي هذا إحاطةُ علمِ الله وإثباتُه كلَّ شيء؛ فاطمئنَّ إلى أنّ الله أحاط بكلِّ شيءٍ علمًا وكتابةً، فلا يضيع عنده عملٌ ولا يُنسى حقّ، وكلُّ شيءٍ محفوظٌ مكتوب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى إحاطةِ علمِ الله وكتابته."},"action":{"text":"اطمئنَّ إلى أنّ الله أحاط بكلِّ شيءٍ علمًا، وأثبت كلَّ غائبةٍ في كتابٍ مبين؛ فلا يضيع عنده عملٌ صالحٌ ولا مظلمةٌ ولا حقّ؛ فاعمل الخيرَ واثقًا بأنه محفوظٌ لك، واحذر الشرَّ فإنه مكتوبٌ عليك؛ فمن علم أنّ أعماله مسجّلةٌ عند الله، أحسن العملَ ورجا ثوابه، ولم ييأس من عدلِ ربّه ورحمته."}}]},{"title":"القرآنُ يفصل، والتوكّل، وحدودُ الهداية","range":[76,81],"theme":"القرآنُ يقصّ الحقَّ ويفصل الخلاف، وهو هدًى ورحمة، والأمرُ بالتوكّل، وأنّ هدايةَ القلوبِ بيدِ الله لا بالنبيّ","verses":[{"n":76,"reflection":{"text":"«إن هذا القرآن يقص على بني إسرائيل أكثر الذي هم فيه يختلفون» — إنّ هذا القرآنَ يبيّن لبني إسرائيلَ أكثرَ ما اختلفوا فيه من الحقّ؛ ففي هذا أنّ القرآنَ فصلٌ للاختلافِ وبيانٌ للحقّ؛ فاجعل القرآنَ حَكَمك عند الاختلاف، فهو يقصّ الحقَّ ويفصل النزاع، ففيه شفاءُ ما اختُلِف فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ القرآنِ حَكَمًا فاصلًا عند الاختلاف."},"action":{"text":"اجعل القرآنَ مرجعك وحَكَمك عند كلِّ اختلافٍ ونزاع، فهو يبيّن الحقَّ ويفصل الخصومات كما يقصّ على بني إسرائيلَ حقيقةَ ما اختلفوا فيه؛ فعند تنازعِ الناسِ في دينٍ أو رأيٍ، ردَّ الأمرَ إلى كتابِ الله؛ ففيه الفصلُ والبيان؛ فمن تحاكم إلى القرآنِ اهتدى، ومن تركه تاه في الأهواءِ المختلفة."}},{"n":77,"reflection":{"text":"«وإنه لهدى ورحمة للمؤمنين» — وإنّ هذا القرآنَ لهدايةٌ ورحمةٌ للمؤمنين؛ ففي هذا أنّ القرآنَ هدًى ورحمةٌ لأهلِ الإيمان؛ فاطلب الهدى والرحمةَ في القرآن، فمن آمن به واتّبعه ناله هداه ورحمته، ومن أعرض حُرِمهما، فالسعادةُ في التمسّكِ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الهدى والرحمةِ في القرآنِ بالإيمانِ به."},"action":{"text":"تمسّك بالقرآنِ تلاوةً وتدبّرًا وعملًا لتنال ما فيه من هدًى ورحمة، فهو «هدى ورحمة للمؤمنين»؛ فمن آمن به واتّبعه هُدِي قلبه ونالته رحمةُ الله، ومن أعرض عنه حُرِم النورَ والرحمة؛ فاجعل القرآنَ ربيعَ قلبك وجلاءَ همّك؛ ففيه سعادةُ الدنيا والآخرةِ لمن أخذ به."}},{"n":78,"reflection":{"text":"«إن ربك يقضي بينهم بحكمه وهو العزيز العليم» — إنّ ربّك يقضي بين المختلفين يومَ القيامةِ بحكمِه العدل، وهو العزيزُ الغالبُ العليمُ بكلِّ شيء؛ ففي هذا أنّ الفصلَ النهائيَّ لله؛ فكِل الخصوماتِ إلى حكمِ الله، فهو العزيزُ الذي ينفذ حكمه، العليمُ الذي لا يخفى عليه شيء، فسيقضي بالحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","العليم"],"heart_state":{"text":"التسليمُ لحكمِ الله العزيزِ العليمِ الفاصلِ بين الخلق."},"action":{"text":"سلّم أمرَ الخصوماتِ والاختلافاتِ التي تُعييك إلى حكمِ الله، فهو الذي يقضي بين عباده بحكمه العدلِ يومَ القيامة؛ فهو العزيزُ الذي ينفذ قضاؤه فلا رادَّ له، العليمُ الذي أحاط بحقائقِ الأمور؛ فاطمئنَّ إلى أنّ الحقَّ سيظهر، والمظلومَ سيُنصَف؛ فلا تجزع لتأخّرِ الحكم، فموعدُه عند العزيزِ العليم."}},{"n":79,"reflection":{"text":"«فتوكل على الله إنك على الحق المبين» — فاعتمد على الله وفوّض أمرك إليه، إنك على الحقِّ الواضح؛ ففي هذا الأمرُ بالتوكّلِ لمن كان على الحقّ؛ فتوكّل على الله ما دمت على الحقِّ البيّن، فمن كان على الحقِّ واتّكل على الله لم يضرّه خذلانُ الناس، فالحقُّ منصورٌ والمتوكّلُ مكفيّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التوكّلُ على الله مع الثباتِ على الحقِّ البيّن."},"action":{"text":"توكّل على الله وفوّض أمرك إليه، مطمئنًّا إلى أنك على الحقِّ الواضحِ البيّن «إنك على الحق المبين»؛ فمن ثبت على الحقِّ واعتمد على الله كفاه وأيّده، ولم يضرّه خذلانُ الناسِ أو كيدُهم؛ فاجمع بين الأمرين: الثباتِ على الحقّ، والتوكّلِ على الله؛ فبهما تُنال العزّةُ والنصرُ والطمأنينة."}},{"n":80,"reflection":{"text":"«إنك لا تسمع الموتى ولا تسمع الصم الدعاء إذا ولوا مدبرين» — إنك لا تُسمع الموتى، ولا تُسمع الصمَّ الدعاءَ إذا أعرضوا مدبرين؛ ففي هذا أنّ هدايةَ القلوبِ بيدِ الله لا بيدك؛ فابذل البلاغَ ولا تكلّف نفسك ما ليس إليك، فليس عليك إسماعُ من أعرض قلبُه، إنما عليك التبليغُ، والهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ البلاغِ وتركُ ما ليس إليك من الهداية."},"action":{"text":"ابذل البلاغَ والنصيحةَ لكلِّ أحد، ولا تحمل نفسك ما ليس إليك من إسماعِ من أصمَّ الله قلبه وأعرض عن الحقِّ مدبرًا؛ فهدايةُ التوفيقِ بيدِ الله لا بيدك «إنك لا تسمع الموتى»؛ فلا تُتعب قلبك حسرةً على المعرضين؛ أدِّ ما عليك من الدعوةِ والبيان، وكِل أمرَ القبولِ إلى الله؛ فالمسؤوليةُ عنك تسقط بالبلاغ."}},{"n":81,"reflection":{"text":"«وما أنت بهادي العمي عن ضلالتهم إن تسمع إلا من يؤمن بآياتنا فهم مسلمون» — وما أنت بهادٍ العميَ عن ضلالتهم، إنما تُسمِع من يؤمن بآياتنا فهم منقادون مسلمون؛ ففي هذا أنّ المنتفعَ بالبلاغِ هو المؤمنُ المستعدُّ للقبول؛ فوجّه دعوتك، واعلم أنّ من يقبل هو صاحبُ القلبِ الحيِّ المؤمن، فلا تأسَ على من أعمى الله قلبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ أنّ المنتفعَ بالدعوةِ صاحبُ القلبِ المؤمن."},"action":{"text":"اعلم أنّ الذي ينتفع بدعوتك وبلاغك هو صاحبُ القلبِ الحيِّ المؤمنِ المستعدِّ للقبولِ والانقياد «إن تسمع إلا من يؤمن بآياتنا»؛ فوجّه جهدك في الدعوة، ولا تحزن على من أعمى الله بصيرته عن الحقّ؛ فلست بمكلَّفٍ بهدايةِ قلوبهم، إنما بالبلاغ؛ فابذله للجميع، واعلم أنّ الثمرةَ عند أهلِ الإيمان، والأجرُ لك على البلاغ."}}]},{"title":"أشراطُ الساعةِ وأهوالُ الحشرِ والجزاء","range":[82,90],"theme":"خروجُ الدابّة، وحشرُ المكذّبين وتوبيخُهم، وآيةُ الليلِ والنهار، والنفخُ في الصورِ وفزعُه، وجزاءُ الحسنةِ بالأمنِ والسيّئةِ بالنار","verses":[{"n":82,"reflection":{"text":"«وإذا وقع القول عليهم أخرجنا لهم دابة من الأرض تكلمهم أن الناس كانوا بآياتنا لا يوقنون» — وإذا حان وقتُ العذابِ ودنت الساعةُ أخرجنا لهم دابّةً من الأرضِ تكلّمهم بأنّ الناسَ كانوا بآياتنا لا يوقنون؛ ففي هذا خروجُ الدابّةِ من أشراطِ الساعةِ الكبرى؛ فآمن بأشراطِ الساعةِ كما أخبر الصادقُ ﷺ، واستعدَّ ليومٍ لا ينفع فيه إيمانٌ لم يسبق، فبادر باليقينِ قبل ظهورِ الآيات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بأشراطِ الساعةِ والمبادرةُ باليقين."},"action":{"text":"آمن بما أخبر الله ورسولُه ﷺ من أشراطِ الساعةِ الكبرى كخروجِ الدابّةِ التي تكلّم الناس؛ واعلم أنّ الإيمانَ لا ينفع بعد ظهورِ الآياتِ العظمى؛ فبادر بترسيخِ يقينك بآياتِ الله والعملِ بها من الآن؛ فمن لم يوقن بالآياتِ في زمنِ الاختيارِ لم ينفعه يقينُ الاضطرارِ عند رؤيةِ الأهوال؛ فاغتنم مهلةَ الإيمانِ قبل فواتها."}},{"n":83,"reflection":{"text":"«ويوم نحشر من كل أمة فوجا ممن يكذب بآياتنا فهم يوزعون» — واذكر يومَ نحشر من كلِّ أمةٍ جماعةً ممّن كذّبوا بآياتنا فهم يُساقون ويُحبَس أوّلهم على آخرهم؛ ففي هذا حشرُ المكذّبين للحساب؛ فاحذر أن تُحشر في زمرةِ المكذّبين، وكن من المصدّقين بآياتِ الله، فيومَ الحشرِ يتميّز أهلُ الحقِّ من أهلِ الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الحشرِ في زمرةِ المكذّبين."},"action":{"text":"احذر أن تكون يومَ القيامةِ في زمرةِ المكذّبين بآياتِ الله الذين يُحشرون للعذاب؛ وكن من المصدّقين بآياتِ الله المؤمنين بها العاملين بمقتضاها؛ فاستحضر ذلك المشهدَ العظيم حين يُساق كلُّ فوجٍ بأعماله؛ فليحملك ذلك على تصديقِ الحقِّ واتّباعه؛ فالمرءُ يومئذٍ مع من صدّق أو كذّب، فاختر لنفسك اليومَ صحبةَ المؤمنين."}},{"n":84,"reflection":{"text":"«حتى إذا جاءوا قال أكذبتم بآياتي ولم تحيطوا بها علما أماذا كنتم تعملون» — حتى إذا جاؤوا للحسابِ قال الله موبّخًا: أكذّبتم بآياتي ولم تحيطوا بها علمًا؟ أم ماذا كنتم تعملون؟ ففي هذا توبيخُ من كذّب بلا علم؛ فلا تكذّب بشيءٍ قبل أن تحيط به علمًا، فالتكذيبُ بالجهلِ جريمةٌ، والعاقلُ يتثبّت قبل أن يحكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التثبّتُ قبل الحكم، وتركُ التكذيبِ بالجهل."},"action":{"text":"لا تكذّب بشيءٍ من الحقِّ أو تنكره قبل أن تحيط به علمًا وتتبيّن حقيقته، فإنّ الله يوبّخ المكذّبين «أكذبتم بآياتي ولم تحيطوا بها علما»؛ فالتكذيبُ بالجهلِ والتسرّعُ في الإنكارِ جريمةٌ يُحاسَب عليها؛ فتوقّف فيما لا تعلم، واطلب العلمَ قبل الحكم؛ فالعاقلُ يتثبّت، والجاهلُ يبادر بالردِّ والإنكار، فيندم يومَ لا ينفع الندم."}},{"n":85,"reflection":{"text":"«ووقع القول عليهم بما ظلموا فهم لا ينطقون» — وحلَّ بهم العذابُ بسببِ ظلمهم فلا ينطقون بحجّة؛ ففي هذا أنّ الظلمَ سببُ العذاب، وأنّ الظالمَ يُخرَس يومئذٍ عن الحجّة؛ فاحذر الظلمَ فإنه سببُ الخزيِ والعذاب، فيومَ القيامةِ لا حجّةَ للظالمِ ولا نطق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الظلمِ الموجبِ للعذابِ والخزي."},"action":{"text":"احذر الظلمَ كلَّه: ظلمَ النفسِ بالمعاصي، وظلمَ الخلقِ بالبغيِ عليهم؛ فالظلمُ سببُ وقوعِ العذابِ والخزيِ يومَ القيامة، حتى يُخرَس الظالمُ عن الحجّة «فهم لا ينطقون»؛ فردَّ المظالمَ إلى أهلها، وتُب من كلِّ ظلم؛ فمن سلم من الظلمِ نطق بالحجّةِ يومئذٍ وأمِن، ومن ظلم بُهِت وخزي؛ فالظلمُ ظلماتٌ يومَ القيامة."}},{"n":86,"reflection":{"text":"«ألم يروا أنا جعلنا الليل ليسكنوا فيه والنهار مبصرا إن في ذلك لآيات لقوم يؤمنون» — ألم يروا أنا جعلنا الليلَ ليستريحوا فيه والنهارَ مضيئًا ليبتغوا فيه معاشهم؟ إنّ في ذلك لآياتٍ لقومٍ يؤمنون؛ ففي هذا الاستدلالُ بنعمةِ الليلِ والنهارِ على القدرةِ والرحمة؛ فتأمّل نعمةَ تعاقبِ الليلِ والنهار، واشكر واهبها، فمن سخّر لك الزمانَ لسكنك ومعاشك يستحقّ عبادتك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمةِ الليلِ والنهارِ وشكرُ واهبها."},"action":{"text":"تأمّل نعمةَ الله في جعلِ الليلِ سكنًا تستريح فيه، والنهارِ مبصرًا تبتغي فيه رزقك؛ واستدلَّ بهذا التدبيرِ المحكمِ على قدرةِ الله ورحمته ووحدانيته؛ فاشكر واهبَ هذه النعمةِ بحسنِ استعمالها: الليلِ في راحةٍ وعبادة، والنهارِ في سعيٍ حلالٍ وطاعة؛ فمن رأى في تعاقبهما آياتِ الله ازداد إيمانًا وشكرًا."}},{"n":87,"reflection":{"text":"«ويوم ينفخ في الصور ففزع من في السماوات ومن في الأرض إلا من شاء الله وكل أتوه داخرين» — واذكر يومَ يُنفخ في الصورِ ففزع من في السماواتِ والأرضِ إلا من شاء الله، وكلٌّ أتوه صاغرين ذليلين؛ ففي هذا هولُ النفخِ في الصورِ وذلُّ الخلقِ لله؛ فاستحضر هولَ ذلك اليوم، واعمل لما ينجّيك من فزعه، فالكلُّ يومئذٍ خاضعٌ ذليلٌ لله، فأخلص له الخضوعَ اليوم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ هولِ النفخِ في الصورِ والخضوعُ لله."},"action":{"text":"استحضر هولَ يومِ النفخِ في الصورِ حين يفزع أهلُ السماواتِ والأرضِ ويأتون الله صاغرين أذلّاء؛ فاعمل من الآن لما يؤمّنك من فزعِ ذلك اليوم بالإيمانِ والعملِ الصالح؛ وأخلص خضوعك وذلّك لله اختيارًا في الدنيا قبل أن تُذلَّ اضطرارًا يومَ القيامة؛ فمن خضع لله طائعًا هنا، أمِن فزعَ يومِ ينفخ في الصور."}},{"n":88,"reflection":{"text":"«وترى الجبال تحسبها جامدة وهي تمر مر السحاب صنع الله الذي أتقن كل شيء إنه خبير بما تفعلون» — وترى الجبالَ تحسبها ثابتةً وهي تسير سيرَ السحابِ يومَ القيامة، صنعَ الله الذي أحكم كلَّ شيء، إنه خبيرٌ بأعمالكم؛ ففي هذا عظمُ قدرةِ الله وإتقانُ صنعه وإحاطةُ خبرته؛ فتأمّل إتقانَ الله لخلقه، واعلم أنه خبيرٌ بعملك، فأتقن عملك كما أتقن خلقك، فالمتقِنُ يحبّ الإتقان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الخبير"],"heart_state":{"text":"التأمّلُ في إتقانِ صنعِ الله وإتقانُ العمل."},"action":{"text":"تأمّل قدرةَ الله وإتقانه لخلقه، حتى الجبالُ الراسيةُ تسير يومَ القيامةِ بأمره «صنع الله الذي أتقن كل شيء»؛ واعلم أنه خبيرٌ بكلِّ ما تفعل؛ فأتقن عملك وعبادتك ومعاملتك اقتداءً بإتقانِ خالقك، ومراقبةً لخبرته بك؛ فالله يحبّ من العبدِ إذا عمل عملًا أن يتقنه؛ فاجعل الإحسانَ والإتقانَ دأبك في كلِّ ما تصنع."}},{"n":89,"reflection":{"text":"«من جاء بالحسنة فله خير منها وهم من فزع يومئذ آمنون» — من جاء يومَ القيامةِ بالحسنةِ (وأعظمُها التوحيد) فله خيرٌ منها، وهم من فزعِ ذلك اليومِ آمنون؛ ففي هذا فضلُ الحسناتِ وأمنُ أهلها؛ فأكثر من الحسناتِ لا سيّما التوحيد، فبها الأمنُ يومَ الفزعِ الأكبر، والثوابُ المضاعف؛ فاجعل رصيدك من الحسناتِ وافرًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من الحسناتِ لنيلِ الأمنِ يومَ الفزع."},"action":{"text":"أكثر من الحسناتِ والأعمالِ الصالحة، وعلى رأسها توحيدُ الله وإخلاصُ العبادةِ له؛ فمن جاء بها يومَ القيامةِ فله خيرٌ منها من الثوابِ المضاعف، وهو آمنٌ من فزعِ ذلك اليوم «وهم من فزع يومئذ آمنون»؛ فاجعل همّك تكثيرَ رصيدك من الخيرات؛ فبها تنال الأمنَ يومَ يفزع الناس، والفوزَ برضوانِ الله وجنّته؛ فبادر بالحسناتِ ما دمت في مهلة."}},{"n":90,"reflection":{"text":"«ومن جاء بالسيئة فكبت وجوههم في النار هل تجزون إلا ما كنتم تعملون» — ومن جاء بالسيّئةِ (وأعظمُها الشرك) فأُلقيت وجوههم في النارِ منكّسين، ويُقال: هل تُجزَون إلا بأعمالكم؟ ففي هذا عدلُ الجزاءِ بالسيّئة؛ فاحذر السيّئاتِ لا سيّما الشرك، فجزاؤها النارُ والخزي، والجزاءُ من جنسِ العمل، فما تزرعه تحصده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من السيّئاتِ التي جزاؤها النارُ والخزي."},"action":{"text":"احذر السيّئاتِ والمعاصي، وأعظمُها الشركُ بالله، فإنّ جزاءها الخزيُ وإلقاءُ الوجوهِ في النار «فكبت وجوههم في النار»؛ واعلم أنّ الجزاءَ من جنسِ العمل، فما قدّمت من خيرٍ أو شرٍّ لقيته؛ فطهّر عملك من السيّئات، وبادر بالتوبةِ عمّا سلف؛ فالله عدلٌ لا يظلم أحدًا، «هل تجزون إلا ما كنتم تعملون»؛ فاختر لنفسك ما تحبّ أن تلقاه."}}]},{"title":"خاتمةُ السورة: عبادةُ ربِّ البلدةِ وتلاوةُ القرآنِ والحمد","range":[91,93],"theme":"الأمرُ بعبادةِ ربِّ البلدةِ الحرامِ والإسلامِ له، وتلاوةِ القرآنِ فمن اهتدى فلنفسه، وختمُ السورةِ بالحمدِ ووعدِ إظهارِ الآيات","verses":[{"n":91,"reflection":{"text":"«إنما أمرت أن أعبد رب هذه البلدة الذي حرمها وله كل شيء وأمرت أن أكون من المسلمين» — قل: إنما أُمِرتُ أن أعبد ربَّ هذه البلدةِ (مكةَ) الذي حرّمها وجعلها آمنة، وله كلُّ شيء، وأُمِرتُ أن أكون من المسلمين المنقادين؛ ففي هذا إخلاصُ العبادةِ لربِّ البلدةِ الحرام؛ فأخلص عبادتك لله مالكِ كلِّ شيء، وكن من المسلمين المنقادين لأمره، فالعبادةُ حقّه وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العبادةِ لله مالكِ كلِّ شيءٍ والانقيادُ له."},"action":{"text":"أخلص عبادتك لله ربِّ كلِّ شيءٍ ومالكه، الذي حرّم البلدةَ وأمّنها؛ وكن من المسلمين المنقادين لأمره ظاهرًا وباطنًا كما أُمِر النبيُّ ﷺ؛ فاجعل عبادتك خالصةً له وحده، وسلّم أمرك كلَّه إليه؛ فمن أفرد الله بالعبادةِ وانقاد لشرعه فقد حقّق الغايةَ التي خُلِق لها؛ فالزم الإسلامَ والاستسلامَ لله في كلِّ شأنك."}},{"n":92,"reflection":{"text":"«وأن أتلو القرآن فمن اهتدى فإنما يهتدي لنفسه ومن ضل فقل إنما أنا من المنذرين» — وأُمِرتُ أن أتلوَ القرآنَ وأبلّغه، فمن اهتدى فلنفسه، ومن ضلَّ فقل: إنما أنا من المنذِرين ليس عليّ هداكم؛ ففي هذا أنّ ثمرةَ الهدى للمهتدي، وأنّ مهمّةَ الرسولِ الإنذار؛ فاتلُ القرآنَ واعمل به، واعلم أنّ هدايتك لنفسك، فبادر إليها، ولا تكلّف الداعيَ نتيجةَ من ضلّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تلاوةُ القرآنِ والاهتداءُ به، فالهدى للنفس."},"action":{"text":"اتلُ القرآنَ وتدبّره واعمل به، واعلم أنّ من اهتدى فإنما ثمرةُ هداه له وحده «فمن اهتدى فإنما يهتدي لنفسه»؛ فبادر إلى هدايةِ نفسك ولا تفرّط؛ وإذا دعوت غيرك فليس عليك إلا الإنذارُ والبلاغ لا ضمانُ الهداية؛ فاجعل حظّك من القرآنِ العملَ به لا مجرّدَ تلاوته؛ فالسعيدُ من اهتدى، وليس على المبلِّغِ إلا النذارة."}},{"n":93,"reflection":{"text":"«وقل الحمد لله سيريكم آياته فتعرفونها وما ربك بغافل عما تعملون» — وقل: الحمدُ لله، سيريكم اللهُ آياتِه في الآفاقِ وأنفسِكم فتعرفونها، وما ربّك بغافلٍ عمّا تعملون؛ ففي هذا ختمُ السورةِ بالحمدِ والوعيدِ اللطيف؛ فاختم أمورك بالحمد، واعلم أنّ الله سيُظهر آياتِه ولن تخفى، وأنه غيرُ غافلٍ عن عملك، فراقبه في كلِّ حال، فما من عملٍ إلا وهو محصًى عليك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ختمُ الأمورِ بالحمدِ ومراقبةُ الله غيرِ الغافل."},"action":{"text":"اختم أعمالك وأحوالك بحمدِ الله والثناءِ عليه كما ختم السورةَ «وقل الحمد لله»؛ وأيقن أنّ الله سيُري الناسَ آياتِه في الآفاقِ وأنفسِهم حتى تتبيّن، وأنه ليس بغافلٍ عن شيءٍ من عملك؛ فراقبه في سرّك وعلنك، وأحسن العمل؛ فمن استحضر أنّ الله لا يغفل عنه، اجتهد في طاعته، وحمده على نعمه، واستعدَّ للقائه، غيرَ مغترٍّ بإمهاله."}}]}],"coverage":{"covered":93,"total":93}};
